window.TRANS_DATA=[{"block":"Processos Administrativos e Legislação","code":"1.1","title":"Recrutamento e Seleção","overview":"Recrutamento e seleção são etapas diferentes do provimento de pessoas. O recrutamento forma o conjunto de candidatos; a seleção compara evidências e escolhe quem melhor atende ao perfil do cargo. Em prova, a banca costuma trocar o nome das etapas, então é essencial reconhecer a finalidade de cada ação.","concepts":[{"term":"Recrutamento interno","text":"Busca candidatos no próprio quadro. Aproveita histórico e reduz adaptação, mas limita a entrada de repertório externo e pode gerar competição interna."},{"term":"Recrutamento externo","text":"Busca candidatos no mercado por portais, escolas, agências, redes profissionais ou banco de currículos. Amplia opções, porém costuma exigir mais tempo e integração."},{"term":"Recrutamento misto","text":"Combina fontes internas e externas. Continua sendo uma estratégia de atração, não uma técnica de seleção."},{"term":"Seleção","text":"Usa critérios e instrumentos — triagem, provas, testes, entrevistas e avaliações práticas — para comparar candidato e requisito do cargo."},{"term":"Validade e confiabilidade","text":"Validade é o quanto o instrumento mede o que importa para o cargo; confiabilidade é a consistência do resultado."},{"term":"Perfil do cargo","text":"Conjunto de responsabilidades, requisitos e competências usado como referência para decidir quem deve ser atraído e como será avaliado."}],"process":["Definir necessidade e perfil da vaga.","Escolher fontes de recrutamento.","Atrair e receber candidaturas.","Triar requisitos mínimos.","Aplicar técnicas de seleção.","Decidir com base em evidências e registrar a escolha."],"compare":[["Recrutamento","Atrair candidatos","Anúncio, banco de talentos, indicação"],["Seleção","Comparar e escolher","Prova, entrevista, teste prático"],["Fonte","Onde encontrar candidatos","Site, intranet, escola"],["Técnica","Como avaliar candidato","Entrevista, prova, dinâmica"]],"example":"Uma empresa publica a vaga na intranet e em um portal externo: recrutamento misto. Depois aplica prova de Excel e entrevista estruturada: seleção. A prova de Excel não é “fonte de recrutamento”.","traps":["Entrevista não é recrutamento.","Promoção interna não é sinônimo de recrutamento interno.","Critérios sem relação com o cargo reduzem validade."],"memory":["Recrutamento atrai; seleção escolhe.","Perfil do cargo orienta os critérios.","Validade = aderência ao que se pretende medir; confiabilidade = consistência."],"visual":{"type":"flow","title":"Fluxo de provimento","nodes":["Necessidade","Perfil","Recrutamento","Triagem","Seleção","Admissão"],"caption":"Atração vem antes da avaliação seletiva."},"formula":null,"sources":[],"id":"processos-recrutamento-e-selecao"},{"block":"Processos Administrativos e Legislação","code":"1.2","title":"Plano de Cargos e Carreira","overview":"Planos de cargos e carreira organizam o trabalho em posições, classes, níveis e trajetórias. Eles servem para dar coerência a responsabilidades, requisitos, remuneração e possibilidades de crescimento, evitando decisões improvisadas.","concepts":[{"term":"Cargo","text":"Conjunto relativamente estável de atribuições e responsabilidades. O cargo existe na estrutura independentemente da pessoa que o ocupa."},{"term":"Descrição de cargo","text":"Registra o que é feito, para que, com quais responsabilidades e em quais condições."},{"term":"Especificação","text":"Registra requisitos para ocupação: escolaridade, experiência, conhecimentos e competências."},{"term":"Avaliação de cargos","text":"Compara valor relativo dos cargos para estruturar hierarquia interna; não avalia o desempenho da pessoa."},{"term":"Faixa salarial","text":"Intervalo remuneratório associado a um nível ou classe, normalmente com mínimo, referência e máximo."},{"term":"Carreira em Y","text":"Permite evolução pela trilha técnica ou gerencial, evitando que o único caminho de crescimento seja virar chefe."}],"process":["Analisar e descrever cargos.","Avaliar valor relativo.","Agrupar em níveis/classes.","Definir faixas e critérios de movimentação.","Comunicar regras de progressão.","Revisar o plano quando o trabalho muda."],"compare":[["Descrição","O que o cargo faz","Conteúdo do trabalho"],["Especificação","O que o ocupante precisa ter","Requisitos"],["Avaliação de cargo","Valor estrutural do cargo","Não é desempenho"],["Avaliação de desempenho","Entrega da pessoa no período","Não redefine o cargo"]],"example":"Dois empregados podem ocupar o mesmo cargo e receber valores diferentes dentro da faixa conforme regras de progressão. Isso não significa que o “cargo de um vale mais” do que o do outro.","traps":["Cargo não é a pessoa.","Avaliação de cargo e de desempenho são coisas diferentes.","Carreira não é apenas promoção vertical."],"memory":["Descrição = atribuições.","Especificação = requisitos.","Carreira = trajetória.","Faixa salarial é intervalo, não valor único."],"visual":{"type":"flow","title":"Estrutura de carreira","nodes":["Cargo","Classe","Nível","Faixa","Progressão","Trilha técnica/gerencial"],"caption":"O plano conecta estrutura do trabalho e desenvolvimento."},"formula":null,"sources":[],"id":"processos-plano-de-cargos-e-carreira"},{"block":"Processos Administrativos e Legislação","code":"1.3","title":"Treinamento, Desenvolvimento e Educação","overview":"Treinamento, desenvolvimento e educação lidam com aprendizagem no trabalho, mas com horizontes diferentes. O processo profissional começa pelo diagnóstico da lacuna e termina pela verificação de transferência e resultado; oferecer curso, por si só, não prova melhoria.","concepts":[{"term":"Treinamento","text":"Foco mais imediato no desempenho atual: conhecimento, habilidade e atitude necessários às tarefas presentes."},{"term":"Desenvolvimento","text":"Amplia capacidades para responsabilidades futuras e crescimento de carreira."},{"term":"Educação corporativa","text":"Organiza aprendizagem contínua alinhada à estratégia, podendo envolver trilhas, academias, cursos e comunidades de prática."},{"term":"Diagnóstico de necessidades","text":"Verifica se a causa da lacuna é realmente falta de conhecimento/habilidade. Falta de sistema, recurso ou processo não se resolve apenas com curso."},{"term":"Transferência","text":"Uso efetivo do que foi aprendido no trabalho. Depende de apoio, oportunidade, recursos e reforço."},{"term":"Avaliação","text":"Pode medir reação, aprendizagem, comportamento/transferência e resultados. Satisfação não é prova de aprendizagem."}],"process":["Diagnosticar a lacuna.","Definir objetivo observável.","Desenhar método e conteúdo.","Executar a ação.","Avaliar aprendizagem e transferência.","Ajustar com base nos resultados."],"compare":[["Treinamento","Desempenho atual","Horizonte mais curto"],["Desenvolvimento","Capacidade futura","Horizonte mais amplo"],["Educação","Formação contínua e estratégica","Sistema de aprendizagem"]],"example":"Se a equipe erra porque o sistema está indisponível, treinamento não resolve a causa. Se erra porque não sabe operar uma função do sistema, treinamento pode ser adequado.","traps":["Nem toda lacuna de desempenho é lacuna de treinamento.","Avaliação de reação mede percepção, não competência.","Sem oportunidade de uso, o aprendizado pode não se transferir."],"memory":["Diagnóstico antes do curso.","Treinar = presente; desenvolver = futuro.","Aprender só gera valor quando aparece no trabalho."],"visual":{"type":"flow","title":"Ciclo de T&D","nodes":["Diagnóstico","Objetivos","Desenho","Execução","Avaliação","Transferência"],"caption":"A avaliação alimenta o próximo diagnóstico."},"formula":null,"sources":[],"id":"processos-treinamento-desenvolvimento-e-educacao"},{"block":"Processos Administrativos e Legislação","code":"1.4","title":"Gerenciamento de Desempenho","overview":"Gerenciar desempenho é um ciclo contínuo de expectativas, acompanhamento, feedback, avaliação e desenvolvimento. Uma nota anual é apenas um registro; o sistema de desempenho existe durante todo o período.","concepts":[{"term":"Meta","text":"Resultado esperado com indicador, valor-alvo e prazo. Uma boa meta precisa ser clara e ligada ao trabalho."},{"term":"Indicador","text":"Medida usada para acompanhar execução ou resultado. Sem referência ou meta, o número não diz sozinho se está bom ou ruim."},{"term":"Feedback","text":"Informação específica sobre comportamento e efeito observado, dada a tempo de orientar manutenção ou mudança."},{"term":"Avaliação 90/180/360°","text":"Modelos com diferentes fontes de avaliação. 360° agrega múltiplos observadores, mas precisa de critérios e confidencialidade adequados."},{"term":"Vieses","text":"Halo, recência, tendência central, leniência, severidade e semelhança podem distorcer julgamento."},{"term":"Plano de desenvolvimento","text":"Transforma lacunas identificadas em ações, responsáveis e prazos."}],"process":["Pactuar expectativas.","Acompanhar evidências.","Dar feedback ao longo do ciclo.","Avaliar resultados e competências.","Definir reconhecimento ou correção.","Planejar desenvolvimento."],"compare":[["Gestão de desempenho","Ciclo completo","Contínuo"],["Avaliação","Momento de julgamento/registro","Parte do ciclo"],["Potencial","Capacidade futura estimada","Não é desempenho atual"]],"example":"Um empregado bate a meta de volume, mas aumenta o retrabalho. Um sistema equilibrado não olha só quantidade; inclui qualidade e comportamentos críticos.","traps":["Recência supervaloriza eventos próximos à avaliação.","Resultado em um único KPI pode esconder efeitos colaterais.","Feedback anual e tardio é insuficiente para corrigir rota."],"memory":["Gestão de desempenho é ciclo.","Meta define o alvo; indicador mede.","Evidências e feedback reduzem subjetividade."],"visual":{"type":"flow","title":"Ciclo de desempenho","nodes":["Metas","Acompanhamento","Feedback","Avaliação","Desenvolvimento"],"caption":"A gestão acontece durante todo o período."},"formula":null,"sources":[],"id":"processos-gerenciamento-de-desempenho"},{"block":"Processos Administrativos e Legislação","code":"1.5","title":"Gestão por Competências","overview":"Gestão por competências liga estratégia e pessoas. A organização define quais capacidades precisa, mede o que possui e trata os gaps por desenvolvimento, recrutamento, movimentação ou redesenho do trabalho.","concepts":[{"term":"Conhecimento","text":"Saber conceitual: normas, princípios, informações e modelos necessários para compreender a atividade."},{"term":"Habilidade","text":"Saber fazer: capacidade de aplicar conhecimento e executar a tarefa com qualidade."},{"term":"Atitude","text":"Disposição e padrão de comportamento ao agir, como iniciativa, responsabilidade e cooperação."},{"term":"Competência organizacional","text":"Capacidade coletiva importante para executar a estratégia, como excelência logística ou segurança operacional."},{"term":"Competência individual","text":"Entrega e comportamento esperados de uma pessoa em determinado papel."},{"term":"Gap","text":"Diferença entre o nível requerido e o disponível. Pode direcionar várias ações, não apenas treinamento."}],"process":["Traduzir estratégia em competências.","Mapear por processos/cargos.","Definir níveis de proficiência.","Avaliar situação atual.","Identificar gaps.","Priorizar ações para fechar lacunas."],"compare":[["Competência","Capacidade demonstrada em contexto","Entrega observável"],["Qualificação","Formação/requisito formal","Não prova desempenho"],["Gap","Requerido menos disponível","Origina plano de ação"]],"example":"Uma área precisa de análise de dados. Nível básico interpreta relatórios; intermediário cria painéis; avançado modela dados. O gap é medido contra o nível exigido para cada papel.","traps":["Certificado não prova competência sozinho.","Competência deve ser descrita de forma observável.","Gap pode exigir recrutamento ou redesign, não só curso."],"memory":["CHA ajuda a decompor competência.","Competência se confirma na entrega.","Gap = requerido − existente."],"visual":{"type":"triangle","title":"Competência na prática","nodes":["Conhecimento","Habilidade","Atitude"],"caption":"Saber + saber fazer + agir no contexto."},"formula":null,"sources":[],"id":"processos-gestao-por-competencias"},{"block":"Processos Administrativos e Legislação","code":"1.6","title":"Relações de Trabalho e Benefícios","overview":"Relações de trabalho combinam dimensão jurídica e gerencial: regras, diálogo, condições de trabalho, negociação, conflitos e recompensas. Benefícios fazem parte da recompensa total e precisam de critérios de elegibilidade, custo, comunicação e conformidade.","concepts":[{"term":"Remuneração direta","text":"Salário e parcelas pagas diretamente pelo trabalho, conforme natureza jurídica de cada verba."},{"term":"Benefícios","text":"Vantagens ou serviços como assistência, alimentação, transporte e previdência, com tratamento jurídico dependente da forma e da norma aplicável."},{"term":"Relações coletivas","text":"Negociação entre trabalhadores/representantes e empregadores, com acordos e convenções coletivas."},{"term":"Clima organizacional","text":"Percepções sobre ambiente de trabalho. Afeta comportamento, mas não substitui direitos nem conformidade."},{"term":"Administração de benefícios","text":"Controla elegibilidade, fornecedores, custo, utilização, qualidade e comunicação."},{"term":"Conflito","text":"Pode ser administrado por negociação, mediação e regras; conflito não significa necessariamente relação disfuncional."}],"process":["Mapear obrigações legais/coletivas.","Definir política interna.","Estabelecer elegibilidade.","Contratar/gerir fornecedores.","Comunicar condições.","Monitorar custo, uso e conformidade."],"compare":[["Salário","Contraprestação principal","Remuneração direta"],["Benefício","Vantagem/serviço ligado ao vínculo","Remuneração indireta em sentido gerencial"],["Acordo coletivo","Sindicato profissional + empresa","Âmbito específico"],["Convenção coletiva","Sindicatos profissional + patronal","Categoria/abrangência definida"]],"example":"Ao analisar assistência médica, a empresa não olha só o preço: acompanha elegibilidade, coparticipação, rede, utilização, qualidade e regras contratuais.","traps":["Acordo e convenção coletiva não são sinônimos.","Benefício oferecido pela empresa não vira salário automaticamente em todos os casos.","Política interna deve respeitar normas superiores."],"memory":["Recompensa total vai além do salário.","Benefício precisa de regra e controle.","Relações de trabalho envolvem diálogo e conformidade."],"visual":{"type":"flow","title":"Recompensa total","nodes":["Salário","Incentivos","Benefícios","Ambiente","Desenvolvimento"],"caption":"Vários elementos compõem a proposta ao trabalhador."},"formula":null,"sources":[],"id":"processos-relacoes-de-trabalho-e-beneficios"},{"block":"Processos Administrativos e Legislação","code":"2.1","title":"Princípios de Integração de Sistemas de Gestão","overview":"Um Sistema de Gestão Integrado reúne processos e controles de diferentes disciplinas — por exemplo qualidade, meio ambiente e saúde e segurança — em uma arquitetura comum. Integrar não é apenas juntar manuais; é reduzir duplicidade e gerir objetivos, riscos, documentos, auditorias e indicadores de forma coerente.","concepts":[{"term":"Abordagem por processos","text":"Enxerga entradas, atividades, saídas, responsáveis, riscos e indicadores, conectando áreas que antes eram tratadas isoladamente."},{"term":"PDCA","text":"Planejar, executar, verificar e agir. O ciclo estrutura controle e melhoria."},{"term":"Contexto e partes interessadas","text":"A organização identifica fatores internos/externos e expectativas relevantes que afetam o sistema."},{"term":"Riscos e oportunidades","text":"Planejamento considera incertezas que podem afetar objetivos."},{"term":"Documentação integrada","text":"Um mesmo procedimento pode atender requisitos de várias disciplinas quando o processo é comum."},{"term":"Governança","text":"Papéis, responsabilidades, recursos e prestação de contas sustentam o sistema integrado."}],"process":["Entender contexto.","Mapear processos e requisitos.","Identificar riscos e oportunidades.","Executar controles.","Medir e auditar.","Corrigir desvios e melhorar."],"compare":[["Integração","Arquitetura comum de gestão","Processos compartilhados"],["Certificação","Reconhecimento formal quando aplicável","Não é sinônimo de SGI"],["Procedimento","Como executar uma atividade","Pode atender vários requisitos"]],"example":"Um único procedimento de controle de documentos pode atender qualidade, meio ambiente e SST. Criar três procedimentos idênticos para a mesma rotina é coexistência, não integração eficiente.","traps":["SGI não elimina requisitos específicos.","Integração acontece nos processos, não só no nome do manual.","Auditorias combinadas ainda precisam respeitar critérios de cada sistema."],"memory":["Processos comuns são o eixo do SGI.","PDCA liga planejamento, execução, avaliação e melhoria.","Risco integra diferentes disciplinas."],"visual":{"type":"venn","title":"Sistema de Gestão Integrado","nodes":["Qualidade","Meio ambiente","Saúde e segurança"],"caption":"A zona comum representa processos de gestão compartilhados."},"formula":null,"sources":["https://www.iso.org/management-system-standards.html"],"id":"processos-principios-de-integracao-de-sistemas-de-gestao"},{"block":"Processos Administrativos e Legislação","code":"2.2","title":"Auditorias Internas e Ações Corretivas/Preventivas","overview":"Auditoria interna é processo sistemático, documentado e objetivo para comparar evidências com critérios. Seu propósito é verificar conformidade e eficácia e gerar informação para melhoria, não encontrar culpados.","concepts":[{"term":"Critério","text":"Referência de comparação: norma, procedimento, requisito legal, política ou contrato."},{"term":"Evidência","text":"Informação verificável obtida por registros, observação, entrevista e outras fontes."},{"term":"Constatação","text":"Resultado da avaliação da evidência frente ao critério."},{"term":"Não conformidade","text":"Não atendimento de requisito. Deve ser descrita com evidência e referência objetiva."},{"term":"Correção","text":"Elimina o problema observado naquele momento."},{"term":"Ação corretiva","text":"Elimina a causa para prevenir recorrência. Precisa de análise de causa e verificação de eficácia."},{"term":"Prevenção","text":"Atua antes da ocorrência; em modelos atuais, é fortemente incorporada pela gestão de riscos."}],"process":["Planejar auditoria.","Definir escopo e critérios.","Coletar evidências.","Registrar constatações.","Comunicar resultados.","Tratar causas e verificar eficácia."],"compare":[["Correção","Trata o efeito imediato","Ex.: refazer registro"],["Ação corretiva","Trata a causa","Evita repetição"],["Prevenção/risco","Age antes do problema","Evita ocorrência potencial"]],"example":"Auditoria encontra calibração vencida. Trocar o instrumento é correção. Descobrir que não há alerta de vencimento e implementar controle com responsável e verificação é ação corretiva.","traps":["Opinião não é evidência.","Auditor deve preservar objetividade e independência.","Ação corretiva não termina antes de verificar eficácia."],"memory":["Auditoria = critério versus evidência.","Correção trata efeito; ação corretiva trata causa.","Eficácia precisa ser verificada."],"visual":{"type":"flow","title":"Do achado à eficácia","nodes":["Critério","Evidência","Achado","Causa","Ação","Eficácia"],"caption":"O ciclo só fecha quando a ação funciona."},"formula":null,"sources":["https://www.iso.org/standard/19011.html"],"id":"processos-auditorias-internas-e-acoes-corretivas-preventivas"},{"block":"Processos Administrativos e Legislação","code":"2.3","title":"Melhoria Contínua e Gestão Integrada de Riscos","overview":"Melhoria contínua usa evidências para elevar desempenho ao longo do tempo. Gestão de riscos identifica incertezas, avalia probabilidade e impacto, escolhe respostas e acompanha o risco residual.","concepts":[{"term":"Risco","text":"Efeito da incerteza sobre objetivos. Pode trazer ameaça ou oportunidade."},{"term":"Probabilidade e impacto","text":"Eixos comuns de priorização; ajudam a comparar riscos, mas não tornam a avaliação totalmente objetiva."},{"term":"Controle","text":"Medida que modifica risco: preventiva, detectiva ou corretiva."},{"term":"Tratamento","text":"Evitar, reduzir, compartilhar/transferir, aceitar ou explorar, conforme natureza e estratégia."},{"term":"Risco residual","text":"Parcela que permanece após controles."},{"term":"PDCA","text":"Melhoria contínua liga plano, execução, verificação e ajuste."}],"process":["Definir objetivo e contexto.","Identificar eventos e causas.","Analisar probabilidade, impacto e controles.","Priorizar.","Tratar.","Monitorar risco residual e mudanças."],"compare":[["Perigo","Fonte de dano","Muito usado em SST"],["Risco","Incerteza sobre objetivo","Probabilidade/efeito"],["Problema","Evento já ocorrido","Exige correção/ação corretiva"]],"example":"Fornecedor crítico pode atrasar. A empresa reduz risco homologando alternativa, criando estoque de segurança e monitorando lead time. Ainda sobra um risco residual.","traps":["Matriz de risco não cria certeza matemática.","Aceitar risco é decisão consciente, não ignorar.","PDCA não termina no Check; Act fecha o ciclo."],"memory":["Gerir risco = identificar, analisar, tratar e monitorar.","Controles reduzem risco, não necessariamente eliminam.","Melhoria contínua usa dados e aprendizado."],"visual":{"type":"flow","title":"Ciclo de risco e melhoria","nodes":["Identificar","Analisar","Avaliar","Tratar","Monitorar","Melhorar"],"caption":"O processo se repete conforme contexto e desempenho."},"formula":null,"sources":[],"id":"processos-melhoria-continua-e-gestao-integrada-de-riscos"},{"block":"Processos Administrativos e Legislação","code":"3.1","title":"Controle e Inventário Patrimonial","overview":"Controle patrimonial rastreia bens da incorporação à baixa. Inventário é a verificação física e documental que compara o que existe com o que o sistema diz existir, permitindo corrigir localização, responsabilidade, perdas e registros.","concepts":[{"term":"Tombamento","text":"Identificação patrimonial individual que associa código a dados do bem."},{"term":"Carga patrimonial","text":"Vincula o bem a unidade, local ou responsável."},{"term":"Inventário físico","text":"Confere existência, estado e localização."},{"term":"Conciliação","text":"Compara físico e sistema e trata divergências."},{"term":"Movimentação","text":"Transferência deve atualizar registros para preservar rastreabilidade."},{"term":"Baixa","text":"Retirada formal do bem do controle após hipótese autorizada, com documentação adequada."}],"process":["Registrar aquisição.","Identificar/tombar.","Atribuir localização.","Controlar movimentações.","Inventariar.","Conciliar e, ao fim, baixar."],"compare":[["Cadastro","Registro administrativo","Rastreabilidade"],["Inventário","Verificação física/documental","Confirma cadastro"],["Conciliação","Tratamento da diferença","Resolve divergência"]],"example":"Sistema indica notebook na sala A, mas ele está na sala B. O problema é divergência de localização; não faz sentido baixar um bem que existe.","traps":["Inventário não é depreciação.","Bem não localizado exige apuração antes de ajuste.","Transferência física sem atualização sistêmica enfraquece o controle."],"memory":["Patrimônio precisa de rastreabilidade.","Inventário = físico versus registro.","Divergência deve ser apurada e documentada."],"visual":{"type":"flow","title":"Ciclo patrimonial","nodes":["Aquisição","Registro","Uso","Movimentação","Inventário","Baixa"],"caption":"O cadastro deve acompanhar o bem."},"formula":null,"sources":[],"id":"processos-controle-e-inventario-patrimonial"},{"block":"Processos Administrativos e Legislação","code":"3.2","title":"Classificação, Avaliação e Depreciação de Bens","overview":"Bens precisam ser classificados e mensurados conforme regras contábeis e patrimoniais. Depreciação é a alocação sistemática do valor depreciável ao longo da vida útil — não é sinônimo de preço de mercado caindo.","concepts":[{"term":"Custo","text":"Preço e gastos diretamente atribuíveis para colocar o ativo em condição de uso, conforme norma aplicável."},{"term":"Vida útil","text":"Período ou produção esperada de uso econômico."},{"term":"Valor residual","text":"Valor estimado ao final da vida útil, líquido de custos de alienação."},{"term":"Valor depreciável","text":"Custo menos valor residual."},{"term":"Depreciação linear","text":"Distribui o valor depreciável uniformemente quando o padrão de consumo é aproximadamente constante."},{"term":"Valor contábil","text":"Valor registrado após depreciação e outros ajustes aplicáveis."}],"process":["Classificar o bem.","Determinar custo.","Estimar vida útil e residual.","Escolher método.","Reconhecer depreciação.","Revisar estimativas quando necessário."],"compare":[["Depreciação","Ativo tangível","Alocação sistemática"],["Amortização","Ativo intangível","Conceito análogo em outra natureza"],["Valor de mercado","Preço possível de transação","Não é valor contábil"]],"example":"Máquina custa R$120 mil, residual R$20 mil, vida útil 5 anos. Valor depreciável = R$100 mil; depreciação linear anual = R$20 mil.","traps":["Depreciação não é saída de caixa do período.","Valor residual reduz a base.","Valor contábil não é automaticamente valor de mercado."],"memory":["Valor depreciável = custo − residual.","Linear = valor depreciável ÷ vida útil.","Depreciação reconhece consumo do ativo."],"visual":{"type":"flow","title":"Cálculo da depreciação","nodes":["Custo","− Residual","Valor depreciável","÷ Vida útil","Depreciação"],"caption":"Método linear distribui o valor ao longo do tempo."},"formula":"Depreciação anual (linear) = (Custo − Valor residual) ÷ Vida útil","sources":[],"id":"processos-classificacao-avaliacao-e-depreciacao-de-bens"},{"block":"Processos Administrativos e Legislação","code":"3.3","title":"Gestão de Ativos","overview":"Gestão de ativos busca gerar valor ao longo do ciclo de vida equilibrando desempenho, risco e custo. Vai além do cadastro patrimonial e além da manutenção: começa antes da compra e termina após a retirada.","concepts":[{"term":"Ciclo de vida","text":"Necessidade, projeto/aquisição, comissionamento, operação, manutenção, renovação e descarte."},{"term":"Valor","text":"Benefício financeiro e não financeiro que o ativo entrega aos objetivos."},{"term":"Criticidade","text":"Importância do ativo e consequência de sua falha."},{"term":"Custo do ciclo de vida","text":"Inclui aquisição, energia, operação, manutenção, paradas, risco e descarte."},{"term":"Desempenho","text":"Capacidade do ativo cumprir função requerida."},{"term":"Risco","text":"Incerteza ligada a falha, segurança, ambiente, produção, conformidade ou finanças."}],"process":["Definir objetivos.","Conhecer ativos e condição.","Classificar criticidade.","Planejar ciclo de vida.","Monitorar custo, risco e desempenho.","Decidir renovação/substituição."],"compare":[["Gestão de ativos","Valor no ciclo de vida","Visão ampla"],["Manutenção","Preservar/restaurar função","Parte da gestão"],["Patrimônio","Registrar e controlar bens","Parte administrativa"]],"example":"Uma bomba mais cara pode ser melhor se consumir menos energia, falhar menos e exigir menos peças. Menor preço inicial não significa menor custo de ciclo de vida.","traps":["Preço de compra não é custo total.","Mais manutenção não é sempre melhor.","Ativo crítico merece controles proporcionais ao impacto."],"memory":["Valor = desempenho + risco + custo equilibrados.","Ciclo começa antes da aquisição.","Criticidade orienta prioridade."],"visual":{"type":"flow","title":"Ciclo de vida do ativo","nodes":["Necessidade","Aquisição","Operação","Manutenção","Renovação","Descarte"],"caption":"Decisões iniciais afetam custo e risco futuros."},"formula":null,"sources":["https://www.iso.org/standard/83053.html"],"id":"processos-gestao-de-ativos"},{"block":"Processos Administrativos e Legislação","code":"4.1","title":"Manutenção Corretiva, Preventiva e Preditiva","overview":"Estratégias de manutenção se diferenciam pelo gatilho da intervenção. Corretiva reage à falha; preventiva usa intervalo planejado; preditiva usa condição medida do equipamento para decidir o momento.","concepts":[{"term":"Corretiva","text":"Executada após falha. Pode ser emergencial ou até planejada em ativos não críticos, quando operar até falhar é economicamente aceitável."},{"term":"Preventiva","text":"Executada por tempo, uso ou calendário para reduzir probabilidade de falha."},{"term":"Preditiva","text":"Baseada em condição: vibração, temperatura, óleo, ultrassom, corrente elétrica e outros sinais."},{"term":"Falha potencial","text":"Sinal detectável de degradação antes da falha funcional."},{"term":"MTBF","text":"Tempo médio entre falhas, associado à confiabilidade em certos contextos."},{"term":"MTTR","text":"Tempo médio para reparar/restaurar; reduzi-lo tende a melhorar disponibilidade."}],"process":["Avaliar criticidade.","Analisar falhas.","Escolher estratégia.","Planejar recursos.","Executar e registrar.","Revisar histórico e ajustar estratégia."],"compare":[["Corretiva","Após falha","Restaurar função"],["Preventiva","Por intervalo","Reduzir probabilidade"],["Preditiva","Por condição","Intervir quando necessário"]],"example":"Vibração do rolamento cresce e atinge limite; a troca é programada para a próxima parada: preditiva. Trocar a cada 6 meses, independentemente da condição: preventiva.","traps":["Preditiva não é “adivinhar”.","Preventiva em excesso também custa e pode introduzir falha.","Corretiva pode ser racional em item não crítico."],"memory":["Corretiva = depois.","Preventiva = intervalo.","Preditiva = condição.","MTBF ↑ e MTTR ↓ favorecem disponibilidade."],"visual":{"type":"flow","title":"Da condição à falha","nodes":["Normal","Degradação","Sinal detectável","Intervenção","Falha evitada"],"caption":"A preditiva busca agir na janela entre sinal e falha."},"formula":"Disponibilidade aproximada = MTBF ÷ (MTBF + MTTR)","sources":[],"id":"processos-manutencao-corretiva-preventiva-e-preditiva"},{"block":"Processos Administrativos e Legislação","code":"4.2","title":"Planejamento e Controle da Manutenção","overview":"PCM organiza demanda, prioridade, recursos, programação, execução e aprendizado. Planejamento define o que e como fazer; programação define quando e com quem; controle compara planejado e realizado.","concepts":[{"term":"Ordem de serviço","text":"Registro da demanda e execução, com ativo, atividade, prioridade, recursos, tempos e histórico."},{"term":"Backlog","text":"Carteira de serviços pendentes; precisa ser classificada por prioridade, criticidade e prontidão."},{"term":"Planejamento","text":"Define escopo, método, peças, ferramentas, mão de obra, segurança e duração estimada."},{"term":"Programação","text":"Distribui serviços em calendário compatível com operação e recursos."},{"term":"Indicadores","text":"Disponibilidade, MTBF, MTTR, aderência, backlog e custo ajudam a avaliar o sistema."},{"term":"Histórico","text":"Dados confiáveis de falhas e reparos melhoram planos e análise de causa."}],"process":["Receber solicitação.","Priorizar.","Planejar.","Programar.","Executar e registrar.","Analisar e melhorar."],"compare":[["Planejamento","O que/como/com quais recursos","Prepara o trabalho"],["Programação","Quando/quem","Monta a agenda"],["Controle","Planejado versus realizado","Gera aprendizado"]],"example":"Há troca de lâmpada e vazamento em equipamento crítico. Prioridade não deve ser “primeiro que chegou”; deve considerar impacto, risco e criticidade.","traps":["Backlog precisa ser qualificado, não só contado.","Fechar OS sem dados destrói o histórico.","Urgência e criticidade não são a mesma coisa."],"memory":["PCM integra demanda, recursos e agenda.","Prioridade considera risco/criticidade.","Histórico é matéria-prima da melhoria."],"visual":{"type":"flow","title":"Fluxo do PCM","nodes":["Solicitação","Prioridade","Planejamento","Programação","Execução","Análise"],"caption":"Os dados reais retornam ao planejamento."},"formula":null,"sources":[],"id":"processos-planejamento-e-controle-da-manutencao"},{"block":"Processos Administrativos e Legislação","code":"5.1","title":"Acompanhamento de Indicadores","overview":"Indicadores traduzem desempenho em medidas. Para serem gerenciáveis, precisam de definição, fórmula, fonte, periodicidade, responsável, meta e regra de interpretação.","concepts":[{"term":"Métrica","text":"Qualquer medida quantitativa. Nem toda métrica é um indicador-chave."},{"term":"KPI","text":"Indicador-chave ligado a objetivo crítico e decisão gerencial."},{"term":"Meta","text":"Valor/faixa desejada em prazo definido."},{"term":"Baseline","text":"Valor inicial de referência para medir evolução."},{"term":"Leading","text":"Indicador antecedente que sinaliza fatores que podem influenciar resultado futuro."},{"term":"Lagging","text":"Indicador de resultado já ocorrido, como falhas ou acidentes."},{"term":"Ficha do indicador","text":"Documento que padroniza conceito, fórmula, unidade, fonte, frequência, responsável e meta."}],"process":["Vincular a objetivo.","Definir fórmula.","Definir fonte e frequência.","Estabelecer meta/referência.","Acompanhar série histórica.","Analisar e agir."],"compare":[["Métrica","Medida","Pode ser operacional"],["KPI","Métrica crítica","Ligada à decisão"],["Meta","Valor desejado","Não é indicador"]],"example":"“Número de ordens” sozinho diz pouco. Combinar com atraso, reincidência, criticidade e disponibilidade pode transformar dados em informação útil.","traps":["Indicador sem fórmula padronizada não é comparável.","Um único mês pode enganar.","Meta e indicador são coisas diferentes."],"memory":["Indicador mede; meta direciona.","KPI precisa de decisão associada.","Série histórica dá contexto."],"visual":{"type":"flow","title":"Indicador bem definido","nodes":["Objetivo","Fórmula","Fonte","Meta","Frequência","Ação"],"caption":"Sem ação associada, o painel vira decoração."},"formula":null,"sources":[],"id":"processos-acompanhamento-de-indicadores"},{"block":"Processos Administrativos e Legislação","code":"5.2","title":"Análise de Indicadores para Tomada de Decisão","overview":"Analisar indicadores é transformar número em decisão. Comparar com meta é só o início: é preciso avaliar tendência, variabilidade, segmentação e causa provável antes de agir.","concepts":[{"term":"Tendência","text":"Direção consistente ao longo do tempo."},{"term":"Variação","text":"Diferença em relação a meta ou referência; precisa ser lida com sazonalidade e variabilidade normal."},{"term":"Segmentação","text":"Separar por unidade, fornecedor, produto ou turno pode revelar onde está o problema."},{"term":"Pareto","text":"Mostra concentração de causas/frequências e ajuda a priorizar."},{"term":"Correlação","text":"Associação entre variáveis; não prova causalidade por si só."},{"term":"Plano de ação","text":"Conecta causa provável, ação, responsável, prazo e critério de eficácia."}],"process":["Validar dados.","Comparar com meta/histórico.","Segmentar.","Investigar causa.","Priorizar ação.","Verificar eficácia."],"compare":[["Dado","Registro bruto","12 falhas"],["Informação","Dado com contexto","12 falhas, +50%"],["Análise","Explicação acionável","8 vieram do mesmo componente"]],"example":"Custo de transporte subiu 15%. Segmentação mostra que o aumento está concentrado em uma única rota após mudança de fornecedor. A ação passa a ser direcionada.","traps":["Correlação não prova causa.","Média pode esconder extremos.","Plano sem critério de eficácia não fecha o ciclo."],"memory":["Valide o dado.","Procure concentração e tendência.","Aja sobre causa, não só sintoma."],"visual":{"type":"bars","title":"Pareto simplificado","nodes":["Causa A","B","C","Outras"],"values":[45,25,15,15],"caption":"Poucas causas podem concentrar grande parte do efeito."},"formula":null,"sources":[],"id":"processos-analise-de-indicadores-para-tomada-de-decisao"},{"block":"Processos Administrativos e Legislação","code":"5.3","title":"Indicadores de Desempenho ESG","overview":"ESG organiza dimensões ambiental, social e de governança. Indicadores ESG só são úteis quando têm escopo, metodologia, unidade e dados rastreáveis.","concepts":[{"term":"Ambiental","text":"Emissões, energia, água, resíduos, efluentes, biodiversidade e eficiência de recursos."},{"term":"Social","text":"Saúde e segurança, diversidade, direitos humanos, pessoas, comunidades e cadeia de fornecedores."},{"term":"Governança","text":"Ética, integridade, controles, riscos, transparência, privacidade e prestação de contas."},{"term":"Absoluto","text":"Mostra total de impacto, como toneladas de CO₂e."},{"term":"Intensidade","text":"Relaciona impacto à atividade, como kg CO₂e por tonelada transportada."},{"term":"Materialidade","text":"Ajuda a priorizar temas relevantes para impactos e decisões."}],"process":["Definir tema e objetivo.","Delimitar escopo.","Coletar dados.","Calcular indicador.","Comparar com meta/histórico.","Comunicar com contexto."],"compare":[["Absoluto","Impacto total","Ex.: 10 mil tCO₂e"],["Intensidade","Impacto por unidade","Ex.: kg CO₂e/t.km"],["Meta ESG","Resultado desejado","Ex.: reduzir intensidade"]],"example":"Se o volume transportado cresce 20% e emissões crescem 5%, o total piorou, mas a intensidade pode melhorar. Os dois indicadores respondem perguntas diferentes.","traps":["ESG não é só meio ambiente.","Intensidade não substitui o total.","Sem metodologia, comparação pode ser enganosa."],"memory":["E, S e G são dimensões diferentes.","Observe escopo e unidade.","Indicador precisa ser rastreável."],"visual":{"type":"flow","title":"Três dimensões ESG","nodes":["E · Ambiental","S · Social","G · Governança"],"caption":"Indicadores se ligam a riscos, impactos e objetivos."},"formula":null,"sources":[],"id":"processos-indicadores-de-desempenho-esg"},{"block":"Finanças e Contabilidade","code":"1.1","title":"Porcentagem e Descontos","overview":"Porcentagem representa uma razão por 100 e aparece em reajustes, descontos, variações e margens. A base de cálculo é o ponto mais importante: percentuais sucessivos atuam sobre valores atualizados, por isso não devem ser somados mecanicamente.","concepts":[{"term":"Taxa percentual","text":"p% = p/100. Para aplicar a taxa sobre um valor V, multiplica-se V por p/100."},{"term":"Fator de aumento","text":"Aumento de p% equivale a multiplicar por 1+p/100."},{"term":"Fator de desconto","text":"Desconto de p% equivale a multiplicar por 1−p/100."},{"term":"Variação percentual","text":"Compara mudança com o valor antigo: (novo−antigo)/antigo."},{"term":"Descontos sucessivos","text":"Aplicam fatores sucessivos. Dois descontos de 10% produzem 0,9×0,9=0,81: desconto total de 19%."},{"term":"Reversão percentual","text":"Uma queda de 20% exige aumento de 25% sobre a nova base para retornar ao valor original."}],"process":["Identificar a base.","Transformar percentual em decimal/fator.","Aplicar na ordem dos eventos.","Comparar final com inicial."],"compare":[["+10% e −10%","Não se anulam","1,10×0,90=0,99"],["20% de 300","60","0,20×300"],["100→120","20%","20/100"]],"example":"R$500 com desconto de 20% e depois 10%: 500×0,80×0,90=R$360. O desconto total é 28%, não 30%.","traps":["Não some percentuais sucessivos.","Variação percentual usa o valor inicial no denominador.","Margem sobre venda e acréscimo sobre custo usam bases diferentes."],"memory":["Use fatores multiplicativos.","Sempre descubra a base.","Percentuais inversos não são simétricos."],"visual":{"type":"flow","title":"Descontos sucessivos","nodes":["R$500","−20%","R$400","−10%","R$360"],"caption":"O segundo desconto atua sobre R$400."},"formula":"Variação % = (Novo − Antigo) ÷ Antigo × 100","sources":[],"id":"financas-porcentagem-e-descontos"},{"block":"Finanças e Contabilidade","code":"1.2","title":"Juros Simples","overview":"Nos juros simples, os juros de cada período são calculados sobre o capital inicial. O crescimento é linear: períodos iguais geram acréscimos absolutos iguais quando taxa e capital permanecem constantes.","concepts":[{"term":"Capital C","text":"Valor inicial aplicado ou emprestado."},{"term":"Taxa i","text":"Percentual por período; precisa estar na mesma unidade temporal de n."},{"term":"Tempo n","text":"Número de períodos de incidência."},{"term":"Juros J","text":"Remuneração: J=C·i·n."},{"term":"Montante M","text":"Capital mais juros: M=C+J=C(1+i·n)."},{"term":"Conversão de unidades","text":"Taxa mensal requer tempo em meses ou conversão coerente."}],"process":["Converter a taxa para decimal.","Compatibilizar taxa e tempo.","Calcular juros.","Somar ao capital."],"compare":[["Simples","Juros sobre C","Linear"],["Composto","Juros sobre saldo","Exponencial"]],"example":"C=R$2.000, i=2% ao mês, n=5: J=2000×0,02×5=200 e M=R$2.200. Cada mês gera R$40.","traps":["2% = 0,02 na fórmula.","Taxa e tempo devem usar a mesma unidade.","Juros do período não entram na base seguinte."],"memory":["J=C·i·n.","M=C(1+i·n).","Crescimento linear."],"visual":{"type":"flow","title":"Juros simples","nodes":["Capital","+ juros 1","+ juros 2","+ juros 3","Montante"],"caption":"Os acréscimos periódicos são iguais."},"formula":"J = C·i·n   |   M = C(1+i·n)","sources":[],"id":"financas-juros-simples"},{"block":"Finanças e Contabilidade","code":"1.3","title":"Juros Compostos","overview":"Nos juros compostos, cada período atualiza o saldo e o próximo juro incide sobre o montante acumulado. É o regime de “juros sobre juros” e gera crescimento exponencial com taxa positiva.","concepts":[{"term":"Montante","text":"M=C(1+i)^n."},{"term":"Juros acumulados","text":"J=M−C."},{"term":"Capitalização","text":"Incorporação do juro ao saldo para formar a próxima base."},{"term":"Fator de acumulação","text":"(1+i)^n resume o crescimento total."},{"term":"Valor presente","text":"C=M/(1+i)^n traz valor futuro para hoje."},{"term":"Taxas equivalentes","text":"Geram o mesmo fator acumulado no mesmo horizonte; não são obtidas por regra proporcional simples."}],"process":["Compatibilizar taxa/período.","Calcular 1+i.","Elevar a n.","Multiplicar por C.","Subtrair C se quiser J."],"compare":[["Simples","M=C(1+in)","Linear"],["Composto","M=C(1+i)^n","Exponencial"]],"example":"R$1.000 a 10% por 2 períodos: M=1000×1,1²=R$1.210. O segundo período rende R$110 porque a base já é R$1.100.","traps":["12% a.a. não é automaticamente igual a 1% a.m. efetivo.","Taxas sucessivas multiplicam fatores.","Para achar capital, divida pelo fator."],"memory":["M=C(1+i)^n.","Saldo acumulado vira nova base.","Taxas equivalentes preservam o mesmo fator."],"visual":{"type":"curve","title":"Crescimento composto","nodes":["C","1","2","3"],"caption":"A curva fica mais inclinada com o tempo."},"formula":"M = C(1+i)^n   |   C = M/(1+i)^n","sources":[],"id":"financas-juros-compostos"},{"block":"Finanças e Contabilidade","code":"2.1","title":"Princípios e Práticas Contábeis Fundamentais","overview":"A contabilidade registra e comunica efeitos patrimoniais e de desempenho. Para prova, o núcleo é entender ativo, passivo, patrimônio líquido, receitas, despesas e regime de competência.","concepts":[{"term":"Ativo","text":"Recurso econômico presente controlado pela entidade decorrente de eventos passados."},{"term":"Passivo","text":"Obrigação presente de transferir recurso econômico."},{"term":"Patrimônio líquido","text":"Interesse residual nos ativos após deduzir passivos."},{"term":"Receita","text":"Aumento de ativos ou redução de passivos que eleva PL, excluídos aportes dos proprietários."},{"term":"Despesa","text":"Redução de ativos ou aumento de passivos que reduz PL, excluídas distribuições aos proprietários."},{"term":"Competência","text":"Reconhece efeitos econômicos quando ocorrem, não apenas quando caixa entra/sai."}],"process":["Identificar fato econômico.","Determinar contas afetadas.","Reconhecer no período correto.","Mensurar.","Registrar e apresentar."],"compare":[["Caixa","Movimento financeiro","Entrada/saída"],["Competência","Momento econômico","Receita/despesa"],["PL","Ativo−Passivo","Residual"]],"example":"Serviço prestado em dezembro e recebido em janeiro: a receita pertence a dezembro pelo regime de competência, embora o caixa só entre em janeiro.","traps":["Receita não é recebimento.","Despesa não é pagamento.","Ativo não é só bem físico."],"memory":["Ativo = Passivo + PL.","Competência separa fato econômico de caixa.","Lucro não é caixa."],"visual":{"type":"flow","title":"Equação patrimonial","nodes":["Ativo","=","Passivo","+","Patrimônio líquido"],"caption":"A estrutura patrimonial precisa permanecer equilibrada."},"formula":null,"sources":["https://www.cpc.org.br/"],"id":"financas-principios-e-praticas-contabeis-fundamentais"},{"block":"Finanças e Contabilidade","code":"2.2","title":"Registros Contábeis e Partidas Dobradas","overview":"Partidas dobradas registram cada fato mantendo igualdade entre débitos e créditos. Débito e crédito são posições técnicas nas contas; não significam automaticamente “entrada” e “saída”.","concepts":[{"term":"Débito e crédito","text":"Ativos/despesas normalmente aumentam a débito; passivos/PL/receitas normalmente aumentam a crédito."},{"term":"Lançamento","text":"Registro com contas, lados, valor, data e histórico."},{"term":"Diário","text":"Organiza lançamentos em ordem cronológica."},{"term":"Razão","text":"Agrupa movimentações por conta e mostra saldo."},{"term":"Balancete","text":"Lista saldos e verifica igualdade total débito/crédito; não detecta todos os tipos de erro."},{"term":"Fato permutativo/modificativo","text":"Classificação didática para alterações de composição patrimonial e/ou PL."}],"process":["Interpretar o fato.","Identificar contas.","Definir aumento/redução.","Determinar débito/crédito.","Registrar valores iguais.","Conferir saldos."],"compare":[["Ativo aumenta","Débito","Caixa, estoque"],["Passivo aumenta","Crédito","Fornecedores"],["Receita aumenta","Crédito","Resultado"],["Despesa aumenta","Débito","Resultado"]],"example":"Compra a prazo de material: débito no ativo/despesa conforme natureza e crédito em fornecedores. Total debitado = total creditado.","traps":["Débito não é dívida.","Crédito não é receita em todo caso.","Balancete equilibrado pode conter erro de classificação."],"memory":["Débitos totais = créditos totais.","Natureza da conta determina o lado.","Diário = cronológico; Razão = por conta."],"visual":{"type":"flow","title":"Partidas dobradas","nodes":["Fato","Contas","Débitos","=","Créditos"],"caption":"O lançamento mantém a igualdade."},"formula":null,"sources":[],"id":"financas-registros-contabeis-e-partidas-dobradas"},{"block":"Finanças e Contabilidade","code":"2.3","title":"Obrigações Acessórias e Controle Fiscal","overview":"Além de pagar tributos, empresas cumprem deveres de escriturar, declarar, emitir documentos e manter registros. O controle fiscal organiza dados, prazos e conciliações para que obrigação principal e acessória sejam cumpridas corretamente.","concepts":[{"term":"Obrigação principal","text":"Tem por objeto pagamento de tributo ou penalidade pecuniária."},{"term":"Obrigação acessória","text":"Dever instrumental de informar, escriturar, emitir ou manter registros."},{"term":"SPED","text":"Infraestrutura de escriturações digitais com vários módulos, não um único “imposto”."},{"term":"ECD","text":"Escrituração Contábil Digital em ambiente SPED."},{"term":"ECF","text":"Escrituração Contábil Fiscal, ligada à apuração/informações fiscais conforme regras vigentes."},{"term":"Conciliação","text":"Compara documentos, registros contábeis e fiscais para localizar diferenças antes da entrega."}],"process":["Mapear obrigações.","Capturar documentos.","Classificar operações.","Apurar e conciliar.","Transmitir no prazo.","Arquivar comprovantes e tratar erros."],"compare":[["Principal","Pagar","Natureza pecuniária"],["Acessória","Informar/fazer","Instrumental"]],"example":"Pagar tributo no prazo não elimina a obrigação de entregar escrituração exigida. É possível cumprir a principal e descumprir a acessória.","traps":["SPED possui vários módulos.","Acessória pode gerar penalidade se descumprida.","Cadastro incorreto na origem se propaga para declarações."],"memory":["Principal = pagar.","Acessória = informar/escriturar.","Conciliação previne inconsistência."],"visual":{"type":"flow","title":"Ciclo fiscal","nodes":["Documento","Classificação","Apuração","Conciliação","Declaração","Arquivo"],"caption":"Erros de origem chegam ao fim do processo."},"formula":null,"sources":["https://www.gov.br/receitafederal/pt-br/assuntos/orientacao-tributaria/declaracoes-e-demonstrativos/sped"],"id":"financas-obrigacoes-acessorias-e-controle-fiscal"},{"block":"Finanças e Contabilidade","code":"3.1","title":"Fluxo de Caixa: Conceitos e Classificações","overview":"Fluxo de caixa evidencia entradas e saídas de caixa e equivalentes. Na DFC, movimentos são classificados em atividades operacionais, de investimento e de financiamento, permitindo analisar liquidez e geração de recursos.","concepts":[{"term":"Caixa e equivalentes","text":"Numerário, depósitos e aplicações de curtíssimo prazo/alta liquidez que atendem aos critérios contábeis."},{"term":"Operacionais","text":"Atividades principais geradoras de receita e outras não classificadas como investimento/financiamento."},{"term":"Investimento","text":"Aquisição/alienação de ativos de longo prazo e investimentos não equivalentes de caixa."},{"term":"Financiamento","text":"Movimentos que alteram capital próprio e empréstimos/financiamentos."},{"term":"Fluxo realizado","text":"O que efetivamente entrou/saiu."},{"term":"Fluxo projetado","text":"Estimativa futura usada para planejar liquidez."}],"process":["Definir saldo inicial.","Classificar movimentos.","Apurar fluxos por atividade.","Somar variação.","Conciliar com saldo final."],"compare":[["Lucro","Resultado por competência","Pode não virar caixa imediatamente"],["Caixa","Movimento financeiro","Liquidez"],["Projeção","Estimativa futura","Planejamento"]],"example":"Venda a prazo aumenta receita e contas a receber, mas caixa só aumenta no recebimento. Assim, empresa pode ter lucro e falta de caixa ao mesmo tempo.","traps":["Empréstimo recebido entra no caixa, mas não é receita operacional.","Compra de máquina é investimento.","Lucro líquido não é saldo de caixa."],"memory":["Operação, investimento e financiamento.","Lucro ≠ caixa.","Projeção antecipa déficit."],"visual":{"type":"flow","title":"Três fluxos da DFC","nodes":["Operação","Investimento","Financiamento","Variação de caixa"],"caption":"A soma explica a mudança no saldo."},"formula":null,"sources":["https://www.cpc.org.br/Arquivos/Documentos/183_CPC_03_R2_rev%2013.pdf"],"id":"financas-fluxo-de-caixa-conceitos-e-classificacoes"},{"block":"Finanças e Contabilidade","code":"3.2","title":"Métodos Direto e Indireto, Orçamento e Projeções","overview":"O método direto mostra recebimentos e pagamentos operacionais; o indireto parte do resultado e reconcilia itens sem efeito caixa e variações de capital de giro. Na gestão, projeções posicionam entradas e saídas no tempo para antecipar necessidades.","concepts":[{"term":"Método direto","text":"Apresenta classes de recebimentos e pagamentos operacionais."},{"term":"Método indireto","text":"Parte do lucro/prejuízo e ajusta itens sem caixa e capital de giro."},{"term":"Depreciação","text":"Reduz resultado mas não é saída de caixa do período; por isso é adicionada de volta no indireto."},{"term":"Contas a receber","text":"Aumento tende a reduzir caixa operacional na reconciliação, pois parte da receita não foi recebida."},{"term":"Forecast","text":"Projeção atualizada com informações recentes."},{"term":"Análise de desvios","text":"Compara previsto e realizado e busca causas de diferenças."}],"process":["Projetar saldo e movimentos.","No direto, listar recebimentos/pagamentos.","No indireto, partir do resultado.","Ajustar itens sem caixa/capital de giro.","Comparar realizado com projeção.","Revisar premissas."],"compare":[["Direto","Fluxos brutos","Mais intuitivo operacionalmente"],["Indireto","Lucro + ajustes","Explica lucro × caixa"],["Orçamento","Plano aprovado","Referência"],["Forecast","Previsão atualizada","Reestima futuro"]],"example":"Lucro 100, depreciação 20 e contas a receber aumentam 30: simplificando, caixa operacional pelo indireto = 100+20−30=90, antes dos demais ajustes.","traps":["Adicionar depreciação não apaga a despesa contábil.","Saldo mensal positivo pode esconder falta de caixa no meio do mês.","Forecast não é certeza."],"memory":["Direto = recebimentos/pagamentos.","Indireto = lucro + ajustes.","Datas de caixa importam tanto quanto totais."],"visual":{"type":"flow","title":"Lucro até caixa","nodes":["Lucro","+ itens sem caixa","± capital de giro","Caixa operacional","Projeção"],"caption":"Competência e caixa são reconciliados."},"formula":null,"sources":["https://www.cpc.org.br/Arquivos/Documentos/183_CPC_03_R2_rev%2013.pdf"],"id":"financas-metodos-direto-e-indireto-orcamento-e-projecoes"},{"block":"Finanças e Contabilidade","code":"4.1","title":"Balanço Patrimonial e DRE","overview":"O Balanço Patrimonial mostra a posição patrimonial em uma data; a DRE mostra desempenho durante um período. Eles se conectam porque o resultado do período altera o patrimônio líquido.","concepts":[{"term":"Ativo circulante","text":"Recursos de curto prazo/ciclo operacional conforme critérios contábeis."},{"term":"Ativo não circulante","text":"Realizável a longo prazo, investimentos, imobilizado e intangível conforme estrutura aplicável."},{"term":"Passivo","text":"Obrigações circulantes e não circulantes."},{"term":"Patrimônio líquido","text":"Capital, reservas, ajustes e resultados acumulados conforme estrutura."},{"term":"DRE","text":"Receitas, custos e despesas que formam o resultado do período."},{"term":"Regime de competência","text":"Permite que DRE reconheça fatos antes/depois do caixa."}],"process":["Classificar contas no BP.","Reconhecer receitas/despesas na DRE.","Apurar resultado.","Relacionar resultado ao PL.","Analisar estrutura e margens."],"compare":[["Balanço","Fotografia numa data","Posição"],["DRE","Filme de um período","Desempenho"],["Caixa","Conta do BP","Não é lucro"]],"example":"Venda a prazo de R$10 mil com custo R$6 mil gera margem de R$4 mil na DRE; no BP aumenta contas a receber, sem aumentar caixa naquele instante.","traps":["Dívida recebida em dinheiro aumenta caixa e passivo, não receita.","BP e DRE usam horizontes diferentes.","Lucro não é caixa."],"memory":["BP = posição.","DRE = desempenho.","Resultado afeta PL."],"visual":{"type":"flow","title":"Conexão BP e DRE","nodes":["Receitas","− Custos/Despesas","Resultado","Patrimônio líquido","Balanço"],"caption":"O resultado do período flui para o patrimônio líquido."},"formula":null,"sources":["https://www.cpc.org.br/"],"id":"financas-balanco-patrimonial-e-dre"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"1.1","title":"Logística e Cadeia de Suprimentos","overview":"Logística planeja e controla fluxos de materiais, informações e serviços entre origem e consumo. Supply chain management é mais amplo: coordena fornecedores, organização, parceiros e clientes para otimizar o resultado do conjunto, não de um elo isolado.","concepts":[{"term":"Logística de entrada","text":"Suprimento e movimentação de materiais até a organização."},{"term":"Logística interna","text":"Movimentação, armazenagem e abastecimento dentro das operações."},{"term":"Distribuição","text":"Fluxo de produtos até clientes ou pontos de consumo."},{"term":"Logística reversa","text":"Retorno de produtos, embalagens, resíduos ou materiais."},{"term":"Nível de serviço","text":"Capacidade de atender requisitos de disponibilidade, prazo, integridade e confiabilidade."},{"term":"Custo total","text":"Decisão deve considerar transporte, estoque, armazenagem, processamento, perdas e serviço em conjunto."}],"process":["Planejar demanda.","Suprir materiais.","Receber/armazenar.","Abastecer operação.","Distribuir.","Gerenciar retornos e informação."],"compare":[["Logística","Gestão de fluxos","Parte da cadeia"],["Supply chain","Coordenação ponta a ponta","Múltiplas organizações"]],"example":"Reduzir estoque diminui armazenagem, mas pode elevar rupturas e fretes urgentes. A decisão correta olha o custo total e o nível de serviço.","traps":["Menor custo em uma etapa pode piorar o sistema.","Supply chain não é sinônimo de transporte.","Informação também é fluxo logístico."],"memory":["Otimize o sistema inteiro.","Serviço e custo formam trade-offs.","Cadeia de suprimentos é ponta a ponta."],"visual":{"type":"flow","title":"Cadeia de suprimentos","nodes":["Fornecedor","Suprimento","Operação","Distribuição","Cliente","Retorno"],"caption":"Materiais avançam; informações circulam nos dois sentidos."},"formula":null,"sources":[],"id":"logistica-logistica-e-cadeia-de-suprimentos"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"1.2","title":"Sustentabilidade e Logística Verde","overview":"Logística verde reduz impactos ambientais e sociais sem ignorar custo, segurança e nível de serviço. Atua em transporte, energia, embalagem, armazenagem, compras e fluxos reversos.","concepts":[{"term":"Eficiência energética","text":"Menor consumo por unidade de serviço logístico."},{"term":"Emissões","text":"Podem ser medidas em total e intensidade; comparações precisam de escopo e base iguais."},{"term":"Roteirização","text":"Reduz distância, tempo ocioso e consumo quando bem projetada."},{"term":"Consolidação","text":"Aumenta ocupação do veículo e reduz viagens."},{"term":"Logística reversa","text":"Retorna produtos, embalagens ou resíduos para recuperação/descartes adequados."},{"term":"Compras sustentáveis","text":"Incluem critérios ambientais e sociais além de preço e prazo."}],"process":["Mapear impactos.","Medir energia/emissões/resíduos.","Priorizar hotspots.","Redesenhar rota/modal/embalagem.","Monitorar indicadores."],"compare":[["Logística verde","Foco ambiental","Emissões, energia, resíduos"],["Sustentabilidade","Integra ambiental, social e econômico","Visão mais ampla"]],"example":"Consolidar cargas pode reduzir viagens e emissões por tonelada, desde que o atraso para esperar consolidação não destrua o nível de serviço.","traps":["“Verde” não significa impacto zero.","Indicador de intensidade não substitui total.","Menos embalagem pode aumentar avaria."],"memory":["Sustentabilidade exige visão de ciclo de vida.","Otimização deve preservar segurança e serviço.","Meça total e intensidade."],"visual":{"type":"flow","title":"Alavancas verdes","nodes":["Modal","Rota","Ocupação","Energia","Embalagem","Retorno"],"caption":"Várias decisões combinadas reduzem impacto."},"formula":null,"sources":[],"id":"logistica-sustentabilidade-e-logistica-verde"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"1.3","title":"Tecnologias Emergentes em Logística","overview":"Tecnologias emergentes aumentam visibilidade, automação e capacidade analítica. Elas só geram valor quando resolvem um problema real, usam dados confiáveis e estão integradas ao processo.","concepts":[{"term":"IoT","text":"Sensores conectados medem localização, temperatura, vibração, abertura e outras condições."},{"term":"RFID","text":"Identificação por radiofrequência com leitura sem contato visual direto e, conforme sistema, múltiplos itens."},{"term":"IA e analytics","text":"Apoiam previsão, roteirização, manutenção e detecção de anomalias."},{"term":"Blockchain/DLT","text":"Registro distribuído útil em alguns cenários de rastreabilidade; não garante veracidade do dado de entrada."},{"term":"RPA","text":"Automatiza tarefas repetitivas em sistemas."},{"term":"Digital twin","text":"Representação digital atualizada de ativo/processo para monitoramento e simulação."}],"process":["Definir problema.","Mapear dados.","Testar piloto.","Avaliar segurança/custo.","Integrar ao processo.","Monitorar resultado."],"compare":[["Digitalização","Converter/instrumentar informação","Não garante melhoria"],["Automação","Executar tarefa automaticamente","Muda execução"],["Analytics/IA","Apoiar decisão/predição","Depende de dados"]],"example":"Sensor de temperatura só cria valor se houver limite, alerta, responsável e ação definida quando a carga sai da faixa.","traps":["Tecnologia não corrige processo ruim sozinha.","Blockchain não valida origem dos dados.","IA precisa de qualidade e governança."],"memory":["Comece pelo problema.","Dados + integração + ação fecham o ciclo.","Tecnologia é meio, não objetivo."],"visual":{"type":"flow","title":"Ciclo digital logístico","nodes":["Sensor","Rede","Sistema","Analytics","Alerta","Ação"],"caption":"O dado precisa provocar decisão e resposta."},"formula":null,"sources":[],"id":"logistica-tecnologias-emergentes-em-logistica"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"2.1","title":"Tipos de Transporte","overview":"Os modais diferem em custo, capacidade, velocidade, flexibilidade e infraestrutura. A escolha depende da carga, distância, urgência, risco e custo total porta a porta.","concepts":[{"term":"Rodoviário","text":"Alta capilaridade e flexibilidade porta a porta; sensível a tráfego e custo variável."},{"term":"Ferroviário","text":"Alta capacidade e eficiência em corredores de grande volume e longa distância; menor capilaridade."},{"term":"Aquaviário","text":"Grande capacidade e baixo custo unitário em rotas adequadas; menor velocidade e dependência de terminais."},{"term":"Aéreo","text":"Muito rápido e caro; indicado a urgência, alto valor ou perecibilidade específica."},{"term":"Dutoviário","text":"Fluxo contínuo de produtos adequados; alto investimento e baixa flexibilidade de rota."},{"term":"Cabotagem","text":"Transporte marítimo entre portos do mesmo país, útil em corredores costeiros."}],"process":["Caracterizar a carga.","Mapear origem/destino.","Comparar tempo porta a porta.","Comparar custo total.","Avaliar risco e confiabilidade.","Selecionar modal ou combinação."],"compare":[["Rodoviário","Flexibilidade","Porta a porta"],["Ferroviário","Escala","Grandes volumes"],["Aquaviário","Capacidade","Menor velocidade"],["Aéreo","Velocidade","Maior custo"],["Dutoviário","Fluxo contínuo","Rota rígida"]],"example":"Uma carga pesada entre regiões atendidas por ferrovia pode usar trem no trecho principal e caminhão nas pontas. A análise correta é porta a porta.","traps":["Velocidade do veículo não é lead time total.","Menor frete pode elevar estoque em trânsito.","Dutovia tem baixa flexibilidade de rota."],"memory":["Compare capacidade, flexibilidade, tempo e custo.","Custo total inclui transbordo e estoque.","Combinar modais pode ser melhor que usar um só."],"visual":{"type":"flow","title":"Perfis de modais","nodes":["Rodoviário","Ferroviário","Aquaviário","Aéreo","Dutoviário"],"caption":"Nenhum modal é melhor em todos os critérios."},"formula":null,"sources":[],"id":"logistica-tipos-de-transporte"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"2.2","title":"Intermodalidade e Multimodalidade","overview":"As duas combinam modais, mas diferem no arranjo contratual. Na multimodalidade brasileira, a operação usa duas ou mais modalidades sob um único contrato e responsabilidade do Operador de Transporte Multimodal (OTM).","concepts":[{"term":"Intermodalidade","text":"Uso de mais de um modal, podendo haver contratos e responsáveis distintos por trechos."},{"term":"Multimodalidade","text":"Dois ou mais modais sob contrato único e responsabilidade integrada do OTM."},{"term":"OTM","text":"Pessoa jurídica contratada como principal para a operação multimodal, podendo subcontratar transportadores."},{"term":"Transbordo","text":"Transferência entre veículos/modais, com custo, tempo e risco de manuseio."},{"term":"Unidade de carga","text":"Contêiner e outras formas facilitam transferência modal e reduzem manuseio do produto."},{"term":"Terminal","text":"Ponto de integração física e documental entre etapas."}],"process":["Planejar rota e modais.","Definir arranjo contratual.","Preparar unidade de carga.","Coordenar transbordos.","Rastrear documentos/carga.","Entregar e tratar ocorrências."],"compare":[["Intermodal","Vários modais","Pode ter múltiplos contratos"],["Multimodal","2+ modais","Um contrato + OTM"]],"example":"Caminhão + trem + caminhão com contratos separados: intermodal. Um contrato único com OTM para toda a cadeia: multimodal.","traps":["Número de modais sozinho não define multimodalidade.","OTM não precisa possuir todos os veículos.","Transbordo é ponto crítico de risco e tempo."],"memory":["Multimodal = 2+ modais + contrato único + OTM.","Intermodal pode ter contratos separados.","Unidade de carga facilita integração."],"visual":{"type":"flow","title":"Cadeia multimodal","nodes":["Caminhão","Terminal","Ferrovia/Navio","Terminal","Caminhão"],"caption":"Um contrato pode cobrir toda a cadeia multimodal."},"formula":null,"sources":["https://www.gov.br/antt/pt-br/assuntos/cargas/transporte-multimodal-de-cargas"],"id":"logistica-intermodalidade-e-multimodalidade"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"2.3","title":"Regulação e Legislação do Transporte","overview":"A regulação define requisitos de operação, segurança, documentos e responsabilidades conforme modal e tipo de carga. Para prova, identifique primeiro qual modal, qual operação e qual órgão estão envolvidos.","concepts":[{"term":"ANTT","text":"Atua em transportes terrestres federais e temas de multimodalidade dentro de sua competência."},{"term":"ANTAQ","text":"Atua na regulação aquaviária e portuária em sua competência."},{"term":"ANAC","text":"Regula aviação civil e temas associados ao modal aéreo."},{"term":"Documentação","text":"Varia por modal, carga e operação e dá rastreabilidade à responsabilidade."},{"term":"Carga perigosa","text":"Exige classificação, embalagem, sinalização, documentos e requisitos específicos."},{"term":"Responsabilidade","text":"Lei, regulação e contrato definem obrigações por guarda, transporte, avaria e segurança."}],"process":["Identificar modal/jurisdição.","Classificar carga.","Mapear requisitos.","Verificar segurança/documentos.","Executar e manter rastreabilidade."],"compare":[["ANTT","Terrestre federal/multimodal","Rodovia/ferrovia"],["ANTAQ","Aquaviário/portos","Navegação"],["ANAC","Aviação civil","Aéreo"]],"example":"Uma carga perigosa precisa de requisitos específicos além do cadastro do transportador; cadastro não substitui embalagem, sinalização e documentação.","traps":["Não atribua todo transporte à ANTT.","Regra de um modal não migra automaticamente para outro.","Normas podem mudar e devem ser conferidas na fonte oficial."],"memory":["Modal e carga vêm antes da regra.","Documentação sustenta segurança e responsabilidade.","Competência regulatória é específica."],"visual":{"type":"flow","title":"Órgãos por modal","nodes":["ANTT","ANTAQ","ANAC"],"caption":"A autoridade depende do modal e do tema."},"formula":null,"sources":[],"id":"logistica-regulacao-e-legislacao-do-transporte"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"3.1","title":"Classificação de Estoques","overview":"Estoques podem ser classificados por estágio, função, valor, criticidade e comportamento da demanda. Classificar ajuda a aplicar políticas diferentes em vez de tratar todos os itens do mesmo modo.","concepts":[{"term":"Matéria-prima","text":"Material que será transformado."},{"term":"Em processo","text":"Material já em transformação, ainda não concluído."},{"term":"Produto acabado","text":"Item concluído disponível ao cliente/uso final."},{"term":"MRO","text":"Materiais de manutenção, reparo e operações."},{"term":"Segurança","text":"Proteção contra incerteza."},{"term":"Em trânsito","text":"Material deslocando-se entre pontos da cadeia."},{"term":"Obsoleto/inativo","text":"Item sem uso esperado, exigindo tratamento."}],"process":["Identificar função/estágio.","Avaliar consumo/valor.","Avaliar criticidade.","Definir política.","Monitorar giro e obsolescência."],"compare":[["Ciclo","Atende consumo normal","Varia com lote"],["Segurança","Protege incerteza","Buffer"],["Trânsito","Está deslocando","Depende do lead time"]],"example":"Uma peça barata pode parar um terminal; por valor ela pode ser classe C, mas por criticidade é alta.","traps":["ABC não substitui criticidade.","Estoque em trânsito ainda empata capital.","Baixo valor não significa baixa importância."],"memory":["Classifique por mais de um critério.","Criticidade e valor são dimensões diferentes.","Segurança existe para incerteza."],"visual":{"type":"flow","title":"Funções do estoque","nodes":["Ciclo","Segurança","Trânsito","MRO","Obsoleto"],"caption":"Cada categoria existe por uma razão diferente."},"formula":null,"sources":[],"id":"logistica-classificacao-de-estoques"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"3.2","title":"Curva ABC","overview":"A curva ABC prioriza itens pelo valor anual de consumo. Poucos itens A costumam concentrar grande parte do valor movimentado; limites percentuais são políticas, não constantes universais.","concepts":[{"term":"Valor anual","text":"Consumo anual × custo unitário, em formulação clássica."},{"term":"Classe A","text":"Maior impacto econômico; controle mais rigoroso."},{"term":"Classe B","text":"Faixa intermediária."},{"term":"Classe C","text":"Menor participação econômica; pode admitir controle mais simples."},{"term":"Acumulado","text":"Ordena itens do maior para o menor e soma percentuais."},{"term":"Criticidade","text":"Precisa complementar ABC porque impacto operacional pode ser alto mesmo com baixo valor."}],"process":["Calcular valor anual.","Ordenar decrescente.","Calcular percentuais.","Calcular acumulado.","Definir faixas.","Aplicar controle diferenciado."],"compare":[["A","Alto valor acumulado","Controle intenso"],["B","Intermediário","Controle moderado"],["C","Baixo valor","Controle simplificado"]],"example":"100 unidades × R$1.000 = R$100 mil; 10 mil unidades × R$2 = R$20 mil. O primeiro item pesa mais na ABC apesar de vender menos unidades.","traps":["Não classifique só pelo preço unitário.","80/20 é referência, não lei.","Classe C não significa dispensável."],"memory":["ABC usa valor de consumo.","Ordene e acumule percentuais.","Cruze com criticidade."],"visual":{"type":"bars","title":"Curva ABC simplificada","nodes":["A","B","C"],"values":[70,20,10],"caption":"Poucos itens podem concentrar a maior parte do valor."},"formula":"Valor anual de consumo = Consumo anual × Custo unitário","sources":[],"id":"logistica-curva-abc"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"3.3","title":"Políticas de Estoque","overview":"Políticas definem quando repor e quanto pedir. Ponto de pedido, lote, lead time, revisão contínua/periódica e estoque de segurança são os parâmetros centrais.","concepts":[{"term":"Revisão contínua","text":"Monitora estoque continuamente; reposição é acionada ao atingir ponto de pedido."},{"term":"Revisão periódica","text":"Verifica estoque em intervalos fixos e repõe para um nível-alvo."},{"term":"Ponto de pedido","text":"Demanda esperada no lead time + estoque de segurança, na forma básica."},{"term":"Lote","text":"Quantidade solicitada por reposição."},{"term":"Lead time","text":"Tempo total até o item ficar disponível."},{"term":"Cobertura","text":"Quantos períodos de consumo o estoque suporta."}],"process":["Estimar demanda.","Medir lead time.","Definir serviço.","Calcular segurança e ponto de pedido.","Definir lote/revisão.","Monitorar rupturas e excessos."],"compare":[["Contínua","Gatilho: nível","Monitoramento constante"],["Periódica","Gatilho: tempo","Revisão em datas fixas"]],"example":"Demanda 20/dia, lead time 5 dias, segurança 30: ponto de pedido = 20×5+30=130 unidades.","traps":["Ponto de pedido não é lote.","Lead time inclui todas as etapas relevantes.","Mais estoque reduz ruptura, mas aumenta custo."],"memory":["Quando pedir = ponto de pedido.","Quanto pedir = lote/nível-alvo.","Segurança cobre variabilidade."],"visual":{"type":"flow","title":"Reposição","nodes":["Estoque cai","Ponto de pedido","Pedido","Lead time","Recebimento"],"caption":"A segurança protege durante incertezas."},"formula":"PP ≈ Demanda no lead time + Estoque de segurança","sources":[],"id":"logistica-politicas-de-estoque"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"3.4","title":"Estoque de Segurança e Nível de Serviço","overview":"Estoque de segurança protege contra variabilidade de demanda e prazo. Nível de serviço representa o risco de falta aceito; elevá-lo para perto de 100% costuma exigir estoque crescente.","concepts":[{"term":"Variabilidade de demanda","text":"Quanto mais incerto o consumo, maior tende a ser a proteção."},{"term":"Variabilidade de lead time","text":"Atrasos e dispersão do prazo aumentam necessidade de segurança."},{"term":"Nível de serviço de ciclo","text":"Probabilidade de não haver ruptura em um ciclo, em definição comum."},{"term":"Fill rate","text":"Percentual da demanda atendida imediatamente; não é o mesmo que ciclo sem ruptura."},{"term":"Custo de falta","text":"Perda de venda, parada, atraso, penalidade ou risco."},{"term":"Custo de manutenção","text":"Capital, armazenagem, seguro, perda e obsolescência."}],"process":["Definir serviço desejado.","Medir variabilidade.","Calcular segurança.","Incorporar ao PP.","Monitorar ruptura/excesso.","Recalibrar."],"compare":[["Ciclo","Consumo normal","Determinístico em parte"],["Segurança","Proteção","Incerteza"]],"example":"Peça de baixo consumo, mas crítica para operação, pode justificar alto nível de serviço mesmo sendo classe C por valor.","traps":["Nível de serviço precisa de definição.","Segurança não deve cobrir erro crônico de planejamento.","Mais estoque não substitui melhoria de fornecedor."],"memory":["Segurança responde à incerteza.","Serviço e estoque têm trade-off.","Criticidade influencia o serviço desejado."],"visual":{"type":"flow","title":"Serviço e proteção","nodes":["Variabilidade","Estoque de segurança","Menor ruptura","Maior custo"],"caption":"Serviço maior exige mais proteção ou melhor processo."},"formula":null,"sources":[],"id":"logistica-estoque-de-seguranca-e-nivel-de-servico"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"3.5","title":"Tecnologias para Automação de Estoques","overview":"Automação melhora identificação, atualização e rastreabilidade, desde que o evento físico seja registrado corretamente no sistema.","concepts":[{"term":"Código de barras","text":"Identificação óptica de baixo custo e leitura direta."},{"term":"QR Code","text":"Código bidimensional com mais capacidade de dados."},{"term":"RFID","text":"Leitura por radiofrequência, sem visada direta e potencialmente múltipla."},{"term":"WMS","text":"Gerencia recebimento, endereçamento, picking, inventário e expedição."},{"term":"ERP","text":"Integra estoque com compras, finanças e outras áreas."},{"term":"Inventário cíclico","text":"Contagens frequentes por grupos para manter acuracidade."}],"process":["Identificar item.","Registrar recebimento.","Endereçar.","Registrar movimentação.","Separar/expedir.","Inventariar e conciliar."],"compare":[["Código de barras","Óptico","Baixo custo"],["RFID","Radiofrequência","Leitura sem visada"],["WMS","Software de armazém","Orquestra operação"]],"example":"Mover material fisicamente sem registrar no WMS deixa o sistema desatualizado. Automação só funciona quando evento físico vira evento digital.","traps":["RFID não corrige cadastro ruim.","ERP e WMS podem coexistir.","Automação não substitui inventário e governança."],"memory":["Evento físico deve atualizar o sistema.","WMS controla execução do armazém.","RFID amplia rastreabilidade."],"visual":{"type":"flow","title":"Rastreabilidade digital","nodes":["Etiqueta","Leitor","WMS","ERP","Inventário"],"caption":"Cada movimentação precisa deixar registro."},"formula":null,"sources":[],"id":"logistica-tecnologias-para-automacao-de-estoques"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"4.1","title":"Tipos de Armazéns e Funções","overview":"Armazéns recebem, protegem, organizam, separam e expedem materiais. O tipo de instalação depende da função na rede e do perfil de itens.","concepts":[{"term":"Armazém central","text":"Concentra estoque para várias unidades."},{"term":"Centro de distribuição","text":"Focado em fluxo e atendimento de pedidos."},{"term":"Cross-docking","text":"Recebe e redireciona rapidamente, com pouca ou nenhuma estocagem."},{"term":"Matéria-prima","text":"Apoia abastecimento produtivo."},{"term":"Produto acabado","text":"Mantém itens prontos para distribuição."},{"term":"Área especial","text":"Controla temperatura, incompatibilidade, segurança ou requisitos específicos."}],"process":["Receber.","Conferir.","Identificar/endereço.","Armazenar.","Separar/consolidar.","Expedir."],"compare":[["Armazenagem","Mantém estoque","Disponibilidade"],["Cross-docking","Minimiza permanência","Fluxo rápido"]],"example":"No cross-docking, carga recebida é separada por destino e encaminhada à expedição sem ficar longa permanência no estoque.","traps":["CD pode manter estoque.","Cross-docking exige sincronização.","Material especial pode exigir segregação."],"memory":["Armazém executa fluxo, não só guarda.","Cross-docking minimiza permanência.","Tipo de material define requisitos."],"visual":{"type":"flow","title":"Fluxo do armazém","nodes":["Recebimento","Conferência","Armazenagem","Picking","Consolidação","Expedição"],"caption":"Cross-docking encurta o caminho."},"formula":null,"sources":[],"id":"logistica-tipos-de-armazens-e-funcoes"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"4.2","title":"Layout e Organização de Armazéns","overview":"Layout organiza docas, corredores, posições e áreas para reduzir deslocamentos, cruzamentos e riscos. Slotting posiciona itens conforme giro, peso, volume, afinidade e ergonomia.","concepts":[{"term":"Recebimento","text":"Área de descarga, conferência e divergências."},{"term":"Endereçamento","text":"Código inequívoco de rua, módulo, nível e posição."},{"term":"Slotting","text":"Escolha da melhor localização de cada SKU."},{"term":"Picking","text":"Separação de itens para pedidos; grande fonte de esforço operacional."},{"term":"Fluxo U/I/L","text":"Configurações possíveis conforme terreno e processo."},{"term":"Segregação","text":"Separa incompatíveis e fluxos de pedestres/equipamentos."}],"process":["Mapear volumes.","Dimensionar áreas.","Definir endereçamento.","Posicionar por giro/restrição.","Separar fluxos.","Medir distância/produtividade."],"compare":[["Slotting","Onde colocar cada SKU","Produtividade"],["Endereçamento","Como localizar a posição","Rastreabilidade"]],"example":"Itens de alto giro tendem a ficar próximos do picking/expedição, mas peso e segurança podem alterar essa decisão.","traps":["Maior densidade pode reduzir acesso.","“Classe A na frente” não basta se item é pesado/incompatível.","Layout deve prever devoluções e exceções."],"memory":["Menos deslocamento útil = mais produtividade.","Slotting combina vários critérios.","Segurança faz parte do layout."],"visual":{"type":"flow","title":"Layout conceitual","nodes":["Docas","Recebimento","Estoque A","B/C","Picking","Expedição"],"caption":"Fluxos devem evitar cruzamentos desnecessários."},"formula":null,"sources":[],"id":"logistica-layout-e-organizacao-de-armazens"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"4.3","title":"Tecnologias de Armazenagem","overview":"Estruturas de armazenagem equilibram seletividade, densidade, giro e regras FIFO/LIFO. A melhor solução depende do perfil dos SKUs e equipamentos.","concepts":[{"term":"Porta-paletes seletivo","text":"Acesso direto a cada posição; alta seletividade e densidade moderada."},{"term":"Drive-in/drive-through","text":"Alta densidade para poucos SKUs; menor seletividade."},{"term":"Flow rack","text":"Canais por gravidade que favorecem FIFO."},{"term":"Cantilever","text":"Adequado a cargas longas como tubos e perfis."},{"term":"Mezanino","text":"Cria níveis de piso para aproveitar altura."},{"term":"AS/RS","text":"Armazenagem e recuperação automatizadas integradas a software."}],"process":["Caracterizar unidade de carga.","Definir seletividade/densidade.","Definir FIFO/FEFO/LIFO.","Dimensionar capacidade.","Validar equipamentos e segurança."],"compare":[["Seletivo","Acesso direto","Menor densidade relativa"],["Drive-in","Alta densidade","Baixa seletividade"],["Flow rack","Gravidade","Favorece FIFO"],["Cantilever","Carga longa","Braços abertos"]],"example":"Muitos SKUs de baixo volume valorizam seletividade; poucos SKUs de alto volume podem justificar estruturas densas.","traps":["Densidade maior pode reduzir seletividade.","FIFO depende de processo e estrutura.","Automação exige integração/manutenção."],"memory":["Escolha estrutura pelo perfil do item.","Densidade versus seletividade é trade-off.","Flow rack favorece FIFO."],"visual":{"type":"flow","title":"Escolha de armazenagem","nodes":["Perfil do SKU","Seletividade","Densidade","Giro","Equipamento"],"caption":"O perfil operacional define a solução."},"formula":null,"sources":[],"id":"logistica-tecnologias-de-armazenagem"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"5.1","title":"Equipamentos de Movimentação","overview":"Equipamentos transportam, elevam e posicionam materiais. A seleção depende de peso, dimensão, distância, altura, corredor, piso, frequência e segurança.","concepts":[{"term":"Paleteira","text":"Movimento horizontal de paletes em curtas distâncias."},{"term":"Empilhadeira","text":"Move e eleva cargas paletizadas; há modelos para diferentes corredores e ambientes."},{"term":"Esteira/transportador","text":"Fluxo contínuo em rota relativamente fixa."},{"term":"Ponte rolante/talha","text":"Elevação de cargas pesadas em ambiente industrial."},{"term":"AGV/AMR","text":"Movimentação automatizada com diferentes níveis de navegação."},{"term":"Capacidade nominal","text":"Limite depende das condições especificadas, inclusive centro de carga."}],"process":["Caracterizar carga.","Medir distância/altura/frequência.","Verificar ambiente e corredor.","Selecionar equipamento/acessório.","Treinar e inspecionar.","Medir produtividade e dano."],"compare":[["Móvel","Empilhadeira/AMR","Flexível"],["Fixo","Esteira","Rota definida"]],"example":"Esteira é ótima para fluxo repetitivo entre pontos fixos; empilhadeira é mais flexível quando rotas mudam.","traps":["Capacidade nominal não vale para qualquer centro de carga.","Produtividade não justifica risco.","Equipamento precisa ser compatível com piso/ambiente."],"memory":["Carga + rota + altura + frequência.","Fixos ganham em repetição; móveis em flexibilidade.","Segurança é requisito."],"visual":{"type":"flow","title":"Escolha do equipamento","nodes":["Carga","Distância","Altura","Frequência","Flexibilidade","Segurança"],"caption":"O perfil de operação direciona a escolha."},"formula":null,"sources":[],"id":"logistica-equipamentos-de-movimentacao"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"5.2","title":"Princípios de Movimentação Eficiente","overview":"Movimentação eficiente reduz toques, distância, espera e retrabalho sem sacrificar segurança e integridade da carga.","concepts":[{"term":"Minimização de manuseios","text":"Cada toque adiciona custo, tempo e risco de avaria."},{"term":"Fluxo contínuo","text":"Reduz filas e acumulações quando capacidades estão balanceadas."},{"term":"Unitização","text":"Move vários volumes como uma unidade."},{"term":"Ergonomia","text":"Controla peso, repetição, alcance e postura."},{"term":"Padronização","text":"Rotas, embalagens e métodos estáveis facilitam treinamento."},{"term":"Distância","text":"Layout e slotting reduzem deslocamento desnecessário."}],"process":["Mapear movimentações.","Contar toques/distâncias.","Eliminar etapas sem valor.","Unitizar/padronizar.","Redesenhar layout.","Medir produtividade e avaria."],"compare":[["Movimento","Deslocamento físico","Pode não agregar valor"],["Transporte interno","Deslocamento entre etapas","Custo logístico"]],"example":"Se uma caixa passa por três buffers antes de ser armazenada, talvez conferência na doca e endereçamento direto eliminem movimentos.","traps":["Velocidade maior pode só gerar fila adiante.","Rota curta não justifica misturar pedestres e empilhadeiras.","Automatizar desperdício mantém desperdício."],"memory":["Menos toques e menos distância.","Unitize quando adequado.","Segurança limita o projeto."],"visual":{"type":"flow","title":"Fluxo eficiente","nodes":["Receber","Conferir uma vez","Mover direto","Armazenar"],"caption":"Evite buffers e retornos sem necessidade."},"formula":null,"sources":[],"id":"logistica-principios-de-movimentacao-eficiente"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"5.3","title":"Automação na Movimentação de Materiais","overview":"Automação física usa esteiras, sorters, AGVs, AMRs e robôs. O ganho depende de integração com sistemas, estabilidade do processo, capacidade e plano de contingência.","concepts":[{"term":"AGV","text":"Segue rotas/infraestrutura de navegação mais predefinidas."},{"term":"AMR","text":"Navega com maior autonomia e recalcula rotas."},{"term":"Sorter","text":"Classifica volumes automaticamente por destino."},{"term":"Conveyor","text":"Transporta em percurso fixo e fluxo contínuo."},{"term":"WMS/WCS","text":"WMS decide tarefas; sistemas de controle podem orquestrar equipamentos."},{"term":"Disponibilidade","text":"Falha em automação pode concentrar impacto; manutenção e contingência são essenciais."}],"process":["Mapear processo.","Dimensionar pico.","Escolher nível de automação.","Integrar sistemas.","Implementar segurança.","Monitorar disponibilidade."],"compare":[["AGV","Rota estruturada","Previsível"],["AMR","Rota flexível","Adapta navegação"],["Esteira","Rota fixa","Alto fluxo"]],"example":"AMR reduz caminhada no picking, mas se o WMS envia tarefa errada, o robô executa o erro com eficiência.","traps":["Automação não substitui processo estável.","Capacidade média não basta; avalie pico.","Contingência é necessária."],"memory":["Automação depende de integração digital.","Escolha tecnologia pelo padrão do fluxo.","Disponibilidade é KPI central."],"visual":{"type":"flow","title":"Movimentação automatizada","nodes":["WMS","Orquestração","AGV/AMR","Sensor","Confirmação"],"caption":"Execução precisa retornar ao sistema."},"formula":null,"sources":[],"id":"logistica-automacao-na-movimentacao-de-materiais"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"6.1","title":"Tipos e Funções de Embalagem","overview":"Embalagem contém, protege, informa e facilita manuseio. Na logística, níveis primário, secundário e terciário ajudam a compreender sua função.","concepts":[{"term":"Primária","text":"Contato direto com o produto/unidade de venda."},{"term":"Secundária","text":"Agrupa unidades primárias e adiciona proteção."},{"term":"Terciária","text":"Forma unidade logística de transporte/movimentação."},{"term":"Proteção","text":"Resiste a choque, vibração, compressão, umidade e outros riscos."},{"term":"Informação","text":"Rótulo e símbolos apoiam identificação e segurança."},{"term":"Cube utilization","text":"Dimensões influenciam ocupação de palete, veículo e armazém."}],"process":["Caracterizar produto/riscos.","Definir níveis.","Dimensionar resistência.","Projetar para paletização.","Definir identificação.","Testar no ciclo logístico."],"compare":[["Primária","Contato direto","Proteção do produto"],["Secundária","Agrupa primárias","Manuseio"],["Terciária","Transporte","Unitização"]],"example":"Garrafa = primária; caixa com 12 = secundária; caixas paletizadas com filme = unidade terciária de transporte.","traps":["Mais embalagem nem sempre é melhor.","Redução excessiva pode aumentar avaria.","Embalagem deve ser compatível com modal/equipamento."],"memory":["Conter, proteger, informar e movimentar.","Primária, secundária, terciária.","Projeto afeta frete e armazenagem."],"visual":{"type":"flow","title":"Camadas de embalagem","nodes":["Produto","Primária","Secundária","Terciária"],"caption":"Cada camada cumpre função específica."},"formula":null,"sources":[],"id":"logistica-tipos-e-funcoes-de-embalagem"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"6.2","title":"Sustentabilidade dos Materiais de Embalagem","overview":"Sustentabilidade de embalagem exige olhar ciclo de vida: matéria-prima, fabricação, transporte, uso, retorno, reciclagem e descarte.","concepts":[{"term":"Redução","text":"Menos material/volume sem perder função."},{"term":"Reutilização","text":"Múltiplos ciclos com sistema de retorno."},{"term":"Reciclabilidade","text":"Depende do desenho e infraestrutura real."},{"term":"Conteúdo reciclado","text":"Uso de material recuperado."},{"term":"Monomaterial","text":"Pode facilitar reciclagem se tecnicamente adequado."},{"term":"Ciclo de vida","text":"Evita concluir sustentabilidade por uma única característica."}],"process":["Mapear função.","Reduzir massa/volume.","Avaliar material.","Projetar reuso.","Considerar retorno.","Medir avaria/impacto total."],"compare":[["Reciclável","Pode ser reciclado","Depende de infraestrutura"],["Reciclado","Contém material recuperado","Conteúdo"],["Reutilizável","Vários ciclos","Exige retorno"]],"example":"Embalagem retornável pode não ser vantajosa se volta vazia por longa distância; é preciso comparar transporte, vida útil e taxa de retorno.","traps":["Biodegradável não significa impacto zero.","Reciclável em teoria não garante reciclagem real.","Avaria do produto pode custar mais que economia de material."],"memory":["Olhe o ciclo de vida.","Proteção continua essencial.","Redução, reuso e reciclagem são estratégias diferentes."],"visual":{"type":"flow","title":"Ciclo da embalagem","nodes":["Produção","Uso","Retorno","Reuso/Reciclagem","Nova aplicação"],"caption":"Circularidade depende de retorno real."},"formula":null,"sources":[],"id":"logistica-sustentabilidade-dos-materiais-de-embalagem"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"6.3","title":"Unitização de Cargas","overview":"Unitização agrupa volumes menores em uma unidade maior, reduzindo manuseios e facilitando armazenagem e transporte.","concepts":[{"term":"Paletização","text":"Agrupa volumes sobre palete."},{"term":"Conteinerização","text":"Usa contêiner padronizado e facilita intermodalidade."},{"term":"Estivagem","text":"Arranjo e acomodação segura da carga."},{"term":"Amarração","text":"Cintas, filmes e outros meios estabilizam volumes."},{"term":"Padronização","text":"Dimensões compatíveis melhoram uso de racks e veículos."},{"term":"Centro de gravidade","text":"Distribuição de peso inadequada aumenta risco."}],"process":["Agrupar volumes.","Escolher unidade.","Distribuir peso.","Fixar.","Identificar.","Movimentar/desunitizar."],"compare":[["Palete","Plataforma","Movimentação por garfos"],["Contêiner","Unidade fechada","Intermodalidade"]],"example":"100 caixas soltas exigem muitos movimentos; 5 paletes de 20 caixas reduzem manuseios, desde que peso e estabilidade sejam adequados.","traps":["Unitização não autoriza excesso de peso.","Carga precisa ser estável, não só caber.","Conteinerização exige distribuição correta."],"memory":["Unitizar reduz toques.","Padronização aumenta produtividade.","Estabilidade é crítica."],"visual":{"type":"flow","title":"Unitização","nodes":["Caixas","Palete","Filme/cinta","Empilhadeira","Veículo"],"caption":"Muitos volumes viram uma unidade logística."},"formula":null,"sources":[],"id":"logistica-unitizacao-de-cargas"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"6.4","title":"Segurança no Transporte de Cargas","overview":"Segurança de carga envolve acondicionamento, distribuição de peso, amarração, documentação, condição do veículo e resposta a emergências.","concepts":[{"term":"Acondicionamento","text":"Prepara carga para resistir às forças do transporte."},{"term":"Amarração","text":"Impede deslocamento/tombamento."},{"term":"Distribuição de peso","text":"Afeta estabilidade e limites por eixo."},{"term":"Compatibilidade","text":"Algumas cargas exigem segregação."},{"term":"Carga perigosa","text":"Tem requisitos adicionais de classificação, sinalização e documentos."},{"term":"Emergência","text":"Plano define comunicação e resposta a incidentes."}],"process":["Classificar carga.","Selecionar veículo.","Acondicionar/distribuir.","Amarrar.","Conferir documentos.","Inspecionar e monitorar."],"compare":[["Segurança da carga","Evitar avaria/perda","Fixação"],["Segurança operacional","Proteger pessoas/ambiente","Veículo, rota, emergência"]],"example":"Carga pesada mal distribuída pode comprometer estabilidade mesmo com peso total dentro do limite do veículo.","traps":["Peso total adequado não garante distribuição segura.","Documento não substitui amarração.","Carga perigosa exige regras específicas."],"memory":["Segurança começa antes da viagem.","Distribuição e fixação importam.","Carga perigosa requer controles adicionais."],"visual":{"type":"flow","title":"Barreiras de segurança","nodes":["Embalagem","Fixação","Veículo","Condutor","Rota","Emergência"],"caption":"Camadas de proteção reduzem risco."},"formula":null,"sources":[],"id":"logistica-seguranca-no-transporte-de-cargas"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"7.1","title":"Modalidades de Compras e Orçamento","overview":"Compras transforma necessidade em fornecimento adequado, equilibrando especificação, prazo, qualidade, custo total, risco e conformidade.","concepts":[{"term":"Compra spot","text":"Aquisição pontual para necessidade específica."},{"term":"Fornecimento continuado","text":"Contrato para entregas ao longo do tempo."},{"term":"Cotação","text":"Coleta de propostas comparáveis conforme regras aplicáveis."},{"term":"Orçamento estimativo","text":"Referência de valor construída com método adequado."},{"term":"Custo total","text":"Preço + frete + operação + manutenção + risco, conforme objeto."},{"term":"Sourcing","text":"Estratégia de mercado fornecedor e categoria de compra."}],"process":["Definir necessidade.","Especificar.","Estimar valor.","Escolher estratégia/procedimento.","Analisar propostas.","Contratar e receber."],"compare":[["Menor preço","Valor imediato","Pode não ser menor custo total"],["Orçamento","Estimativa de referência","Não é preço final"]],"example":"Bomba barata pode consumir mais energia e exigir peças exclusivas. Uma decisão técnica precisa comparar condições equivalentes e custo do ciclo de vida quando pertinente.","traps":["Comprar não é só emitir pedido.","Especificação ruim compromete toda contratação.","Preço e custo total não são sinônimos."],"memory":["Necessidade bem definida é a base.","Orçamento referencia.","Compare propostas equivalentes."],"visual":{"type":"flow","title":"Funil de compras","nodes":["Necessidade","Especificação","Orçamento","Mercado","Contratação","Recebimento"],"caption":"Erro de especificação se propaga até o fim."},"formula":null,"sources":[],"id":"logistica-modalidades-de-compras-e-orcamento"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"7.2","title":"Planejamento de Compras","overview":"Planejamento antecipa demanda, prazos, orçamento e risco de fornecimento para reduzir urgências e fragmentação.","concepts":[{"term":"Plano de compras","text":"Consolida objetos, quantidades, prazos e valores."},{"term":"Especificação","text":"Define requisitos funcionais/técnicos suficientes e não indevidamente restritivos."},{"term":"Lead time de aquisição","text":"Inclui aprovações, contratação, fabricação, transporte e recebimento."},{"term":"Consolidação","text":"Agrupa necessidades semelhantes quando há ganho de escala."},{"term":"Risco de suprimento","text":"Considera concentração de fornecedores, prazo e criticidade."},{"term":"Make or buy","text":"Decide entre executar internamente ou contratar."}],"process":["Levantar demanda.","Validar necessidade.","Consolidar.","Estimar custo/prazo.","Analisar mercado/risco.","Programar contratação."],"compare":[["Urgência","Resposta rápida","Pode ser falha de planejamento"],["Emergência jurídica","Hipótese legal","Não é sinônimo de pressa"]],"example":"Peça com lead time de 120 dias para parada daqui a 6 meses precisa ter processo iniciado com antecedência, trabalhando a partir da data de necessidade para trás.","traps":["Planejamento não é repetir compra passada.","Consolidar demais pode reduzir flexibilidade.","Prazo do fornecedor é só parte do lead time total."],"memory":["Planeje de trás para frente.","Integre compras, estoque, orçamento e manutenção.","Risco de suprimento define antecedência."],"visual":{"type":"flow","title":"Planejamento reverso","nodes":["Necessidade","Entrega","Contrato","Competição","Especificação","Planejamento"],"caption":"Cada etapa consome tempo."},"formula":null,"sources":[],"id":"logistica-planejamento-de-compras"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"7.3","title":"Lei 13.303/2016 — Licitações e Contratos","overview":"A Lei 13.303/2016 disciplina empresas públicas e sociedades de economia mista e contém regime próprio de licitações e contratos. Para o edital, os arts. 28 a 91 são o núcleo de estudo.","concepts":[{"term":"Âmbito","text":"Empresas públicas, sociedades de economia mista e subsidiárias conforme a lei."},{"term":"Licitação","text":"Regra geral para contratação com terceiros, ressalvadas hipóteses legais."},{"term":"Dispensa","text":"Lei autoriza contratação direta em situação prevista, mesmo havendo competição possível em tese."},{"term":"Inexigibilidade","text":"Competição inviável."},{"term":"Critérios de julgamento","text":"A lei prevê diversos critérios compatíveis com diferentes objetos."},{"term":"Regulamento interno","text":"Detalha procedimentos da empresa dentro do marco legal."},{"term":"Contratos","text":"Formalizam objeto, preço, prazo, responsabilidades, riscos e execução."}],"process":["Planejar e estimar.","Definir licitação ou contratação direta.","Conduzir procedimento.","Julgar e habilitar.","Formalizar contrato.","Fiscalizar e encerrar."],"compare":[["Dispensa","Hipótese legal","Competição pode existir"],["Inexigibilidade","Competição inviável","Não há disputa útil"],["Julgamento","Compara propostas","Critério"],["Habilitação","Verifica capacidade do licitante","Requisitos"]],"example":"Fornecedor exclusivo devidamente caracterizado pode levar à inexigibilidade. Já uma hipótese legal de contratação direta com mercado competitivo caracteriza dispensa.","traps":["Contratação direta não é contratação informal.","Menor preço não supera requisito técnico mínimo.","Julgamento e habilitação são etapas diferentes."],"memory":["Lei 13.303 é central para estatais.","Dispensa ≠ inexigibilidade.","Arts. 28–91 merecem leitura direta."],"visual":{"type":"flow","title":"Contratação em estatal","nodes":["Necessidade","Planejamento","Licitação/direta","Julgamento","Contrato","Gestão"],"caption":"Contratação direta também exige motivação e controle."},"formula":null,"sources":["https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm"],"id":"logistica-lei-13-303-2016-licitacoes-e-contratos"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"7.4","title":"Lei 14.133/2021 e Relação com Estatais","overview":"A Lei 14.133/2021 é a lei geral de licitações administrativas, mas o próprio art. 1º exclui genericamente empresas públicas, sociedades de economia mista e subsidiárias regidas pela Lei 13.303, ressalvadas previsões específicas.","concepts":[{"term":"Lei 14.133","text":"Regime geral para administrações alcançadas pela lei."},{"term":"Lei 13.303","text":"Regime específico das estatais."},{"term":"Natureza da entidade","text":"É o primeiro filtro para saber qual regime jurídico examinar."},{"term":"Remissão específica","text":"Uma regra externa pode ser aplicada quando a legislação fizer remissão expressa."},{"term":"Princípios","text":"Há aproximações entre regimes, mas isso não torna procedimentos idênticos."},{"term":"Cuidado de prova","text":"“Lei mais nova substituiu tudo” é raciocínio incorreto sem verificar âmbito e revogações."}],"process":["Identificar entidade.","Identificar tema.","Localizar regime principal.","Verificar remissões.","Aplicar dispositivo pertinente."],"compare":[["Lei 13.303","Estatais","Central para Transpetro"],["Lei 14.133","Lei geral administrativa","Não substitui genericamente 13.303"]],"example":"A afirmação “toda contratação da Transpetro é regida diretamente pela Lei 14.133” é incorreta como regra geral; o regime próprio das estatais é a Lei 13.303.","traps":["Não conclua revogação só porque uma lei é mais recente.","Princípios semelhantes não igualam procedimentos.","A aplicação depende do texto legal e do tipo de entidade."],"memory":["Transpetro: foco em Lei 13.303.","Lei 14.133 não rege genericamente estatais.","Âmbito da norma vem antes do conteúdo."],"visual":{"type":"flow","title":"Filtro do regime jurídico","nodes":["Qual entidade?","Estatal?","Lei 13.303","Administração direta?","Lei 14.133"],"caption":"Primeiro identifique quem está contratando."},"formula":null,"sources":["https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2021/lei/l14133.htm","https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2016/lei/l13303.htm"],"id":"logistica-lei-14-133-2021-e-relacao-com-estatais"},{"block":"Logística e Gestão da Cadeia de Suprimentos","code":"8.1","title":"Gestão de Contratos: Ciclo, Fiscalização, Riscos e Digitalização","overview":"Gestão contratual acompanha o contrato do planejamento ao encerramento. Fiscalização verifica a execução concreta; gestão coordena prazos, riscos, medições, pagamentos, mudanças e documentação. Sistemas digitais ampliam rastreabilidade, mas não substituem controle.","concepts":[{"term":"Ciclo de vida","text":"Planejamento, contratação, mobilização, execução, medição, mudanças e encerramento."},{"term":"Fiscalização","text":"Compara entrega com escopo, qualidade, quantidade e prazo e registra evidências."},{"term":"Medição/aceite","text":"Quantifica e confirma o que foi efetivamente entregue para apoiar pagamento."},{"term":"Matriz de riscos","text":"Distribui riscos e respostas entre as partes conforme contrato e regime."},{"term":"Aditivo","text":"Instrumento formal de alteração permitida e justificada."},{"term":"Reequilíbrio","text":"Mecanismo jurídico específico para restaurar equação econômico-financeira quando pressupostos estão presentes."},{"term":"Workflow digital","text":"Fluxos eletrônicos de aprovação, assinatura, medição e alerta."},{"term":"Trilha de auditoria","text":"Registro de quem alterou/aprovou o quê e quando."}],"process":["Planejar objeto e riscos.","Formalizar.","Mobilizar.","Fiscalizar/medir.","Gerir mudanças e riscos.","Pagar conforme aceite.","Encerrar e registrar lições."],"compare":[["Gestor","Coordena o contrato","Visão global"],["Fiscal","Verifica execução","Evidência"],["Aditivo","Altera formalmente","Quando permitido"],["Reequilíbrio","Restaura equação","Hipóteses específicas"]],"example":"Se o fornecedor entrega 90 de 100 unidades, a medição deve refletir o que foi aceito. “Pagar 100 e ajustar depois” enfraquece controle e trilha de auditoria.","traps":["Assinatura do contrato inicia, não encerra, a gestão.","Fiscal não deve alterar contrato sem competência.","Mudança verbal e regularização posterior geram risco."],"memory":["Contrato é ciclo.","Aceite precisa de evidência.","Risco e mudança devem ser formalizados.","Digitalização deve preservar trilha de auditoria."],"visual":{"type":"flow","title":"Ciclo contratual","nodes":["Planejar","Contratar","Executar","Fiscalizar","Mudar/Medir","Encerrar"],"caption":"Lições aprendidas retornam ao próximo planejamento."},"formula":null,"sources":[],"id":"logistica-gestao-de-contratos-ciclo-fiscalizacao-riscos-e-digitalizacao"},{"block":"Noções de Informática","code":"1.1","title":"Fundamentos de Computação e Windows 11","overview":"Computação básica envolve hardware, software, processador, memória, armazenamento e sistema operacional. No Windows 11, a prova tende a cobrar funções de componentes, Explorador de Arquivos, configurações, atalhos e ferramentas administrativas.","concepts":[{"term":"Hardware","text":"Parte física: CPU, RAM, SSD/HDD, placa-mãe e periféricos."},{"term":"Software","text":"Programas e instruções; inclui sistema operacional, aplicativos, drivers e utilitários."},{"term":"CPU","text":"Executa instruções. Desempenho depende de arquitetura, núcleos, clock, cache e carga; GHz sozinho não mede tudo."},{"term":"RAM","text":"Memória volátil de trabalho usada pelos programas em execução."},{"term":"Armazenamento","text":"SSD/HDD preservam dados sem energia; SSD tem baixa latência e não usa partes mecânicas como HDD tradicional."},{"term":"Windows 11","text":"Sistema operacional que gerencia processos, memória, arquivos, dispositivos, contas e interface."},{"term":"Explorador de Arquivos","text":"Permite navegar, copiar, mover, renomear, excluir, pesquisar e visualizar propriedades."},{"term":"Gerenciador de Tarefas","text":"Monitora processos, CPU, memória, disco, rede e inicialização de aplicativos."}],"process":["Entrada fornece dados.","CPU processa instruções.","RAM mantém dados de trabalho.","Armazenamento preserva arquivos.","Windows coordena recursos.","Explorador organiza arquivos e pastas."],"compare":[["RAM","Volátil","Trabalho temporário"],["SSD/HDD","Não volátil","Armazenamento"],["Copiar","Mantém original","Cria duplicata"],["Mover","Transfere localização","Sai da origem"],["Atalho","Aponta para alvo","Não é o arquivo original"]],"example":"Ao abrir uma planilha, o arquivo sai do SSD e é carregado na RAM; a CPU executa cálculos. Salvar grava as alterações novamente no armazenamento. Fechar sem salvar pode perder mudanças mesmo que o arquivo original permaneça.","traps":["RAM não é armazenamento permanente.","Renomear .docx para .pdf não converte o conteúdo.","Excluir um atalho normalmente não exclui o arquivo alvo.","Mais GHz não significa automaticamente processador mais rápido."],"memory":["CPU processa; RAM trabalha; SSD/HDD guarda.","Windows é software de sistema.","Copiar mantém; mover transfere; atalho apenas aponta."],"visual":{"type":"flow","title":"Fluxo básico do computador","nodes":["Entrada","CPU","RAM","Armazenamento","Saída"],"caption":"Cada componente cumpre um papel diferente."},"formula":null,"sources":["https://support.microsoft.com/windows"],"id":"nocoes-fundamentos-de-computacao-e-windows-11"},{"block":"Noções de Informática","code":"2.1","title":"Microsoft Office 2024: Word, Excel e PowerPoint","overview":"Office 2024 reúne ferramentas de produtividade. Word trabalha com documentos estruturados; Excel com dados, fórmulas e análises; PowerPoint com apresentações. A banca pode cobrar efeito de comandos, não apenas localização de botões.","concepts":[{"term":"Word — estilos","text":"Estilos aplicam estrutura e formatação consistente e permitem recursos como sumário automático."},{"term":"Word — seções","text":"Quebra de seção permite mudar orientação, margens, cabeçalho e numeração em parte do documento."},{"term":"Excel — referências","text":"A1 é relativa; $A$1 absoluta; $A1 fixa coluna; A$1 fixa linha."},{"term":"Excel — funções","text":"SOMA, MÉDIA, SE, CONT.SE, SOMASES, PROCV, PROCX/XLOOKUP e FILTRO são exemplos relevantes."},{"term":"Excel — tabelas","text":"Tabelas estruturam dados, filtros e referências e se expandem com novas linhas."},{"term":"PowerPoint — mestre","text":"Mestre de Slides controla padrões globais de layouts e objetos comuns."},{"term":"PowerPoint — transição","text":"Efeito entre slides."},{"term":"PowerPoint — animação","text":"Efeito aplicado a objetos dentro do slide."}],"process":["Estruturar o documento/planilha/apresentação.","Escolher ferramenta adequada.","Usar referências e estilos em vez de formatação manual repetitiva.","Validar fórmulas e resultados.","Revisar antes de exportar ou apresentar."],"compare":[["Quebra de página","Nova página","Mesma seção"],["Quebra de seção","Nova seção","Pode mudar layout"],["Transição","Entre slides","Mudança de tela"],["Animação","Objeto no slide","Efeito interno"],["PROCV","Busca na primeira coluna da matriz","Mais restritivo"],["PROCX","Matriz de busca e retorno separadas","Mais flexível"]],"example":"Em Excel, `=B2*C2*(1+$F$1)` pode ser copiada para baixo: B2 e C2 mudam por linha; $F$1 permanece fixa. No Word, usar Título 1/Título 2 é melhor que apenas aumentar a fonte se você quer sumário automático.","traps":["$ em Excel fixa referência, não significa moeda.","SEERRO pode esconder um problema real se usado sem diagnóstico.","Transição e animação não são sinônimos.","Vários Enters não substituem quebra de página/seção."],"memory":["Word: estilos e seções.","Excel: referências e funções.","PowerPoint: mestre, layout, transição e animação."],"visual":{"type":"flow","title":"Três ferramentas do Office","nodes":["Word · texto","Excel · dados","PowerPoint · apresentação"],"caption":"Cada aplicativo tem lógica própria."},"formula":null,"sources":["https://support.microsoft.com/microsoft-365"],"id":"nocoes-microsoft-office-2024-word-excel-e-powerpoint"},{"block":"Noções de Informática","code":"3.1","title":"Internet, Intranet, Navegadores e Segurança da Informação","overview":"Internet é a rede pública global; intranet usa tecnologias semelhantes em ambiente privado. Navegadores acessam recursos por HTTP/HTTPS. Segurança protege confidencialidade, integridade e disponibilidade por camadas técnicas e humanas.","concepts":[{"term":"Internet","text":"Rede global baseada em TCP/IP e interconexão de redes."},{"term":"Intranet","text":"Serviços privados acessíveis a usuários autorizados da organização."},{"term":"URL","text":"Endereço de recurso web."},{"term":"DNS","text":"Resolve nomes de domínio para endereços e outros registros."},{"term":"HTTPS","text":"HTTP protegido por TLS, oferecendo criptografia em trânsito e autenticação do servidor."},{"term":"Cache","text":"Cópias locais de recursos para acelerar carregamento."},{"term":"Cookies","text":"Pequenos dados associados a sites usados para sessão, preferências e outros fins."},{"term":"CIA","text":"Confidencialidade, integridade e disponibilidade são objetivos clássicos de segurança."},{"term":"MFA","text":"Combina dois ou mais fatores de autenticação."},{"term":"Phishing","text":"Engenharia social para induzir a vítima a revelar dados ou executar ação maliciosa."},{"term":"Backup","text":"Cópia de recuperação; precisa ser testada e protegida contra o mesmo incidente que afeta o original."}],"process":["Usuário informa URL.","DNS resolve o domínio.","Navegador estabelece conexão.","HTTPS negocia TLS.","Servidor responde.","Controles de segurança protegem acesso, dispositivo e dados."],"compare":[["Internet","Pública/global","Acesso amplo"],["Intranet","Privada/organizacional","Acesso restrito"],["Autenticação","Quem é você?","Identidade"],["Autorização","O que pode fazer?","Permissão"],["Cache","Recurso local","Desempenho"],["Cookie","Dado associado ao site","Sessão/preferência"]],"example":"O cadeado/HTTPS indica que a comunicação está criptografada com o servidor autenticado por certificado, mas não garante que o conteúdo do site seja legítimo em todos os sentidos. Um phishing também pode usar HTTPS.","traps":["HTTPS não significa “site confiável” automaticamente.","Antivírus não substitui atualização, MFA e treinamento.","Backup conectado permanentemente pode ser atingido por ransomware.","Autenticação não é autorização."],"memory":["Internet ≠ intranet.","DNS resolve nomes.","CIA = confidencialidade, integridade, disponibilidade.","MFA adiciona barreira contra credencial roubada."],"visual":{"type":"flow","title":"Acesso web seguro","nodes":["URL","DNS","TLS/HTTPS","Servidor","Navegador","Usuário"],"caption":"Várias camadas trabalham juntas."},"formula":null,"sources":[],"id":"nocoes-internet-intranet-navegadores-e-seguranca-da-informacao"},{"block":"Noções de Informática","code":"4.1","title":"LGPD: Conceitos, Princípios, Bases Legais e Direitos","overview":"A LGPD disciplina tratamento de dados pessoais. Para prova, domine conceitos, agentes, princípios, bases legais e direitos do titular. Consentimento é apenas uma das bases possíveis e não substitui finalidade, necessidade, segurança e transparência.","concepts":[{"term":"Dado pessoal","text":"Informação relacionada a pessoa natural identificada ou identificável."},{"term":"Dado sensível","text":"Categorias específicas como saúde, biometria vinculada, origem racial/étnica, opinião política e outras listadas na lei."},{"term":"Titular","text":"Pessoa natural a quem os dados se referem."},{"term":"Controlador","text":"Agente que toma decisões referentes ao tratamento."},{"term":"Operador","text":"Realiza tratamento em nome do controlador."},{"term":"Encarregado","text":"Canal entre controlador, titulares e ANPD, com atribuições definidas em lei/regulação."},{"term":"Tratamento","text":"Qualquer operação com dados: coleta, acesso, uso, armazenamento, compartilhamento, eliminação etc."},{"term":"Princípios","text":"Finalidade, adequação, necessidade, livre acesso, qualidade, transparência, segurança, prevenção, não discriminação e responsabilização/prestação de contas."},{"term":"Bases legais","text":"Consentimento, obrigação legal/regulatória, execução de contrato, exercício regular de direitos, proteção da vida, tutela da saúde, legítimo interesse em condições aplicáveis, proteção do crédito e outras hipóteses legais."},{"term":"Direitos","text":"Confirmação, acesso, correção e outros direitos previstos, sujeitos às condições e regulamentações aplicáveis."},{"term":"Segurança e incidentes","text":"Agentes devem adotar medidas técnicas/administrativas e responder a incidentes conforme gravidade e regras vigentes."}],"process":["Definir finalidade.","Verificar dados necessários.","Escolher base legal.","Definir papéis.","Aplicar segurança e transparência.","Atender direitos.","Reter/eliminar conforme fundamento.","Responder a incidentes."],"compare":[["Controlador","Decide","Finalidades e elementos essenciais"],["Operador","Executa em nome do controlador","Segue instruções"],["Encarregado","Canal e orientação","Não substitui controlador"],["Consentimento","Uma base legal","Não é universal"],["Necessidade","Princípio","Limita ao mínimo necessário"]],"example":"Uma empresa decide quais dados de empregados serão usados na folha: controladora. Um fornecedor processa em nome dela: operador nesse contexto. Nem todo tratamento de folha precisa de consentimento, pois outras bases legais podem se aplicar.","traps":["Encarregado não é operador.","Dado disponível publicamente continua podendo ser dado pessoal.","Consentimento não autoriza qualquer finalidade.","Dados sensíveis têm regime específico."],"memory":["Titular = pessoa natural.","Controlador decide; operador executa.","Base legal não se resume a consentimento.","Princípios valem durante todo o ciclo do dado."],"visual":{"type":"flow","title":"Ciclo LGPD","nodes":["Finalidade","Base legal","Minimização","Segurança","Direitos","Retenção/eliminação"],"caption":"Conformidade acompanha o dado do início ao fim."},"formula":null,"sources":["https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","https://www.gov.br/anpd/pt-br"],"id":"nocoes-lgpd-conceitos-principios-bases-legais-e-direitos"}];